ttribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}s:4:\"item\";a:10:{i:0;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"WordPress 7.1.5 – Atualização de Segurança\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:77:\"https://br.wordpress.org/2026/11/18/wordpress-7-1-5-atualizacao-de-seguranca/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 18 Nov 2026 17:36:11 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:12:\"Lançamentos\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:3:\"7.1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://br.wordpress.org/?p=3768\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:412:\"Esta versão de segurança apresenta correções para vários problemas. Como este é um lançamento de segurança, é recomendável que você atualize seus sites imediatamente. Você pode baixar o WordPress 7.1.5 no WordPress.org ou acessar o Painel do WordPress, clicar em “Atualizações” e, em seguida, em “Atualizar agora”. Se você tiver sites compatíveis com atualizações automáticas [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"Andre\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:8489:\"\n<p class=\"wp-block-paragraph\">Esta versão de segurança apresenta correções para vários problemas.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Como este é um lançamento de segurança, é recomendável que você atualize seus sites imediatamente.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Você pode <a href=\"https://wordpress.org/download/\">baixar o WordPress 7.1.5 no WordPress.org</a> ou acessar o Painel do WordPress, clicar em “Atualizações” e, em seguida, em “Atualizar agora”. Se você tiver sites compatíveis com atualizações automáticas em segundo plano, o processo de atualização começará automaticamente.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.1.5 é uma versão de ciclo curto. O próximo grande lançamento será a versão 7.2, atualmente prevista para <strong>8 de dezembro</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Para mais informações, acesse o <a href=\"https://wordpress.org/documentation/wordpress-version/version-7-1-5/\">site HelpHub do WordPress 7.1.5</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Atualizações de segurança incluídas nesta versão</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Uma expressão regular malformada que ampliava a correspondência de tipos de mídia JSON, corrigida como medida de reforço de segurança, relatada por Mo Jangda, da Equipe de Segurança do WordPress.</li>\n\n\n\n<li>Um problema de escalonamento de privilégios em multisite que permitia a um administrador de site assumir o controle de uma conta de Super Admin por meio das prévias de menus do Personalizar, relatado por Yuval Miller.</li>\n\n\n\n<li>Um XSS refletido na janela pop-up legada da biblioteca de mídia, relatado pela Anthropic.</li>\n\n\n\n<li>Um XSS em <code>wp_interactivity_data_wp_context()</code> por meio do namespace do armazenamento, relatado por <a href=\"https://phpc.social/@jrf_nl\">Juliette Reinders Folmer</a>.</li>\n\n\n\n<li>Injeção de SQL em <code>WP_Meta_Query</code> por meio de valores de relação aninhados, relatada por <a href=\"https://yougina.eu/\">Christiaan Swiers</a>.</li>\n\n\n\n<li>Divulgação de informações sem autenticação que expunha termos de taxonomia privados pelo endpoint de pesquisa da API REST, relatada pela Anthropic.</li>\n\n\n\n<li>Divulgação de informações para usuários com papel de Autor ou superior, que expunha endereços de e-mail de usuários pelo endpoint de comentários da API REST, relatada por Ben Bidner, da Equipe de Segurança do WordPress.</li>\n\n\n\n<li>Injeção de SQL por meio da configuração da página inicial nas prévias de conjuntos de alterações do Personalizar, relatada por Rudy Faile, da Equipe de Segurança do WordPress.</li>\n\n\n\n<li>XSS para usuários com papel de Colaborador ou superior por meio de scripts nas respostas de provedores oEmbed, relatado por vvh1te3zz.</li>\n\n\n\n<li>XSS armazenado sem autenticação por meio de atributos de shortcode em comentários, relatado por <a href=\"https://www.linkedin.com/in/rafiemuhammad/\">Rafie Muhammad</a> (Awesome Motive, Inc.).</li>\n\n\n\n<li>Negação de serviço sem autenticação por meio de pingbacks XML-RPC em lote, relatada por <a href=\"https://novamira.ai\">Giovanni Cintolo</a>.</li>\n\n\n\n<li>Divulgação de informações para usuários com papel de Editor ou superior por meio da atribuição de autores a posts e modelos na API REST, relatada por Jarda Snajdr, da Equipe de Segurança do WordPress.</li>\n\n\n\n<li>XSS armazenado para administradores por meio de prévias do Personalizar, relatado por Weston Ruter, da Equipe de Segurança do WordPress.</li>\n\n\n\n<li>Bypass de autorização para usuários com papel de Autor ou superior por meio da edição de comentários na área administrativa, relatado por Jesse McNeil.</li>\n\n\n\n<li>Divulgação de informações para usuários com papel de Assinante ou superior por meio de <code>wp.getComments</code> no XML-RPC, relatada por <a href=\"https://github.com/dlwodnr59\">Jaewook Lee (grze0)</a>.</li>\n\n\n\n<li>Uma alteração de reforço de segurança que remove a variação de incorporação do Imgur do editor de blocos, cujo provedor no servidor já não existe, relatada por <a href=\"https://jackfromeast.github.io/\">Zhengyu Liu</a>, <a href=\"https://jesse-yang.com/\">Jingcheng Yang</a> e <a href=\"https://gvzhong.github.io/\">Gavin Zhong</a>.</li>\n\n\n\n<li>XSS armazenado para usuários com papel de Colaborador ou superior no bloco Data do comentário por meio do formato da data, relatado por Weston Ruter e Jeremy Felt, da Equipe de Segurança do WordPress.</li>\n\n\n\n<li>Escalonamento de privilégios sem autenticação por meio de atributos do bloco Parte do modelo, que poderia levar à execução remota de código, relatado por <a href=\"https://www.linkedin.com/in/logan-homolka/\">Logan Homolka</a>.</li>\n\n\n\n<li>XSS no editor de blocos por meio dos metadados de imagens do Openverse, relatado por <a href=\"https://kq5.jp/about/\">Shu Takahashi</a>, da Velcore Consulting Inc.</li>\n\n\n\n<li>XSS armazenado para usuários com papel de Colaborador ou superior no editor de blocos por meio de nomes de arquivos de mídia ao converter um bloco de mídia em um bloco Arquivo, relatado por CryptoFox.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Agradecimento aos colaboradores do WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Este lançamento foi liderado por <a href=\"https://profiles.wordpress.org/jeremyfelt/\">Jeremy Felt</a>, <a href=\"https://profiles.wordpress.org/jeryj/\">Jerry Jones</a> e <a href=\"https://profiles.wordpress.org/jsnajdr/\">Jarda Snajdr</a>. O WordPress 7.1.5 não teria sido possível sem as contribuições das seguintes pessoas:</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://w.org/@jorbin\">Aaron Jorbin</a>, <a href=\"https://w.org/@adamsilverstein\">Adam Silverstein</a>, <a href=\"https://w.org/@xknown\">Alex Concha</a>, <a href=\"https://w.org/@aduth\">Andrew Duthie</a>, <a href=\"https://w.org/@andrewserong\">Andrew Serong</a>, <a href=\"https://w.org/@vortfu\">Ben Bidner</a>, <a href=\"https://w.org/@yougina\">Christiaan Swiers</a>, <a href=\"https://w.org/@villanovachile\">Daniel Rodriguez</a>, <a href=\"https://w.org/@dmsnell\">Dennis Snell</a>, <a href=\"https://w.org/@ehtis\">Ehtisham Siddiqui</a>, <a href=\"https://w.org/@mamaduka\">George Mamadashvili</a>, <a href=\"https://w.org/@giovannicintolo\">Giovanni Cintolo</a>, <a href=\"https://w.org/@gziolo\">Greg Ziółkowski</a>, <a href=\"https://w.org/@isabel_brison\">Isabel Brison</a>, <a href=\"https://w.org/@jsnajdr\">Jarda Snajdr</a>, <a href=\"https://w.org/@jeremyfelt\">Jeremy Felt</a>, <a href=\"https://w.org/@jeryj\">jeryj</a>, <a href=\"https://w.org/@buffer1024\">Jesse McNeil</a>, <a href=\"https://w.org/@johnbillion\">John Blackbourn</a>, <a href=\"https://w.org/@jonsurrell\">Jon Surrell</a>, <a href=\"https://w.org/@desrosj\">Jonathan Desrosiers</a>, <a href=\"https://w.org/@jrf\">Juliette Reinders Folmer</a>, <a href=\"https://w.org/@kirasong\">Kira Schroder</a>, <a href=\"https://w.org/@lancewillett\">Lance Willett</a>, <a href=\"https://w.org/@logano\">Logan Homolka</a>, <a href=\"https://w.org/@lucatume\">Luca Tumedei</a>, <a href=\"https://w.org/@luisherranz\">luisherranz</a>, <a href=\"https://w.org/@marcs0h\">Marc Montpas</a>, <a href=\"https://w.org/@tyxla\">Marin Atanasov</a>, <a href=\"https://w.org/@batmoo\">Mohammad Jangda</a>, <a href=\"https://w.org/@ntsekouras\">Nik Tsekouras</a>, <a href=\"https://w.org/@peterwilsoncc\">Peter Wilson</a>, <a href=\"https://w.org/@rafiem\">Rafie Muhammad</a>, <a href=\"https://w.org/@ramonopoly\">ramonopoly</a>, <a href=\"https://w.org/@rfaile313\">Rudy Faile</a>, <a href=\"https://profiles.wordpress.org/sergey/\">Sergey Biryukov</a>, <a href=\"https://w.org/@kq5y\">Shu Takahashi</a> e <a href=\"https://w.org/@westonruter\">Weston Ruter</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Como cortesia, as correções de segurança foram retroportadas para todas as versões elegíveis para receber correções de segurança (atualmente até a 4.7). Como lembrete, <strong>apenas a versão mais recente do WordPress recebe suporte ativo</strong>. Os backports estão em andamento e serão disponibilizados à medida que ficarem prontos.</p>\n\n\n\n<p class=\"wp-block-paragraph\">No WordPress 7.0, certificados de 1.024 bits foram removidos dos certificados de raiz agrupados. Como parte deste lançamento, essa alteração também foi aplicada à versão 6.9.12 e às anteriores.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 RC 2 também foi lançado e inclui todas as correções aplicáveis.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"3768\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"WordPress 7.2 Release Candidate 1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:70:\"https://br.wordpress.org/2026/11/17/wordpress-7-2-release-candidate-1/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 17 Nov 2026 16:22:56 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:12:\"Lançamentos\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:3:\"7.2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://br.wordpress.org/?p=3765\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"O primeira release candidate (RC1) do WordPress 7.2 está pronta para baixar e testar!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"Andre\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:10303:\"\n<p class=\"wp-block-paragraph\">O primeira release candidate (RC1) do WordPress 7.2 está pronta para baixar e testar!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Esta versão do WordPress ainda está em desenvolvimento.</strong> Não instale, execute nem teste esta versão em sites de produção ou essenciais para operações críticas. Em vez disso, recomendamos avaliar a RC1 em um servidor e site de testes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Você pode testar o WordPress 7.2 RC1 usando qualquer um dos métodos a seguir:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><thead><tr><th>Método</th><th>Instruções</th></tr></thead><tbody><tr><td><strong>Plugin</strong></td><td>Instale e ative o plugin <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\">WordPress Beta Tester</a> em uma instalação do WordPress. (Selecione o canal “Bleeding edge” e o fluxo “Beta/RC Only”.)</td></tr><tr><td><strong>Baixe diretamente</strong></td><td>Baixe a <a href=\"https://wordpress.org/wordpress-7.2-RC1.zip\">versão RC1 (zip)</a> e instale-a em um site WordPress.</td></tr><tr><td><strong>Linha de comando</strong></td><td>Use este comando do <a href=\"https://make.wordpress.org/cli/\">WP-CLI</a>: <br><code>wp core update --version=7.2-RC1</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use a <a href=\"http://playground.wordpress.net/release\">instância do WordPress Playground</a> para testar o software diretamente no navegador. Não é preciso configurar nada: basta clicar e testar!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">A data prevista para o lançamento final do WordPress 7.2 é <strong>8 de dezembro de 2026</strong>. Confira o <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\">cronograma completo de lançamento</a>. Sua ajuda para testar as versões Beta e RC é essencial para tornar este lançamento o mais estável e poderoso possível. Agradecemos a todas as pessoas que contribuem com os testes!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Continue acompanhando o <a href=\"https://make.wordpress.org/core/\">blog Make WordPress Core</a> e as <a href=\"https://make.wordpress.org/core/tag/7-2\">publicações relacionadas à versão 7.2</a> nas próximas semanas para saber mais.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Mudanças no núcleo desde a versão Beta 5</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Confira o <a href=\"https://br.wordpress.org/2026/10/20/wordpress-7-2-beta-1/\">anúncio da Beta 1</a> para saber mais sobre o WordPress 7.2.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Você pode consultar os detalhes técnicos de todos os problemas corrigidos desde a versão Beta 5 nos links a seguir:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://core.trac.wordpress.org/query?changetime=11%2F10%2F2026..11%2F17%2F2026&amp;milestone=7.2&amp;status=closed&amp;group=component&amp;order=id&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority\">Tíquetes fechados do Trac da versão 7.2</a> desde 10 de novembro de 2026.</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.2?since=2026-11-10&amp;until=2026-11-17\">Tíquetes do Gutenberg para a versão 7.2</a> desde 10 de novembro de 2026.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 RC1 inclui correções adicionais de erros, melhorias de acessibilidade e atualizações de compatibilidade, à medida que o lançamento se aproxima em 8 de dezembro.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Os ajustes recentes incluem correções para o envio de arquivos de mídia no lado do cliente, melhorias no novo recurso de redirecionamento para conteúdo aleatório e uma navegação por teclado melhor, com um link para pular para o conteúdo na barra de administração do WordPress. Outras atualizações aprimoram as mensagens sobre dependências de plugins, as traduções de módulos de script e a confiabilidade das APIs HTML e de Interatividade.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Desenvolvedores também se beneficiarão de novos ajustes na API de Habilidades e de atualizações nas bibliotecas incluídas, como PHPMailer, Requests, getID3 e sodium_compat.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66490\">Trac #66490</a>, <a href=\"https://core.trac.wordpress.org/ticket/66681\">Trac #66681</a>, <a href=\"https://core.trac.wordpress.org/ticket/66625\">Trac #66625</a>, <a href=\"https://core.trac.wordpress.org/ticket/66331\">Trac #66331</a>, <a href=\"https://core.trac.wordpress.org/ticket/66591\">Trac #66591</a>, <a href=\"https://core.trac.wordpress.org/ticket/65984\">Trac #65984</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Melhorias adicionais no editor de blocos</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 RC1 inclui novos ajustes no editor de blocos, com correções para problemas de conteúdo duplicado em blocos, interações por teclado no iOS e pré-visualizações de revisões. As melhorias na API de Interatividade impedem que respostas de navegação desatualizadas substituam conteúdo mais recente. Outras correções aprimoram os fluxos de instalação de plugins, a compatibilidade das imagens destacadas e as sugestões de links. A administração do WordPress também continua adotando ícones SVG modernos.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://github.com/WordPress/gutenberg/pull/86839\">GitHub #86839</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/86703\">GitHub #86703</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/86608\">GitHub #86608</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/78367\">GitHub #78367</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/86854\">GitHub #86854</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Quer saber mais sobre este lançamento? Confira alguns destaques:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Novo tema padrão Ipsum</li>\n\n\n\n<li>Mais opções de design responsivo e controles da Galeria</li>\n\n\n\n<li>Melhorias nos Estilos Globais e nas ferramentas de tipografia</li>\n\n\n\n<li>Notas no Canvas e colaboração aprimoradas</li>\n\n\n\n<li>Novo inspetor de configurações do bloco DataForm</li>\n\n\n\n<li>Envio de arquivos de mídia e processamento de imagens mais rápidos</li>\n\n\n\n<li>Administração do WordPress modernizada com ícones SVG</li>\n\n\n\n<li>Navegação pela administração e carregamento de recursos mais rápidos</li>\n\n\n\n<li>Novo widget “Neste dia” e descoberta de posts aleatórios</li>\n\n\n\n<li>Gerenciamento aprimorado das atualizações de tradução</li>\n\n\n\n<li>Melhorias de acessibilidade e segurança, além de compatibilidade com o PHP 8.6</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">Como você pode contribuir</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress é um software de código aberto, viabilizado por uma comunidade apaixonada de pessoas que colaboram e contribuem para o seu desenvolvimento. Os recursos abaixo apresentam várias maneiras de ajudar a plataforma web de código aberto mais popular do mundo, independentemente do seu nível de conhecimento técnico.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Participe dos testes</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Testar para encontrar problemas é essencial para o desenvolvimento de qualquer software. Também é uma maneira significativa de qualquer pessoa contribuir.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Sua ajuda para testar a versão WordPress 7.2 RC1 é fundamental para garantir que o lançamento final seja o melhor possível. Testar o processo de atualização é essencial, mas experimentar os novos recursos também é muito importante. Este <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\">guia detalhado</a> vai orientar você nos testes dos recursos do WordPress 7.2.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Atualize seu tema ou plugin</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Os produtos de quem desenvolve plugins e temas são essenciais para ampliar os recursos e o valor do WordPress para todas as pessoas.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Agradecemos por continuar testando seus temas e plugins com as versões Beta do WordPress 7.2. Com a RC1, é hora de concluir os testes e atualizar para 7.2 a versão indicada em <em>“Tested up to”</em> no <a href=\"https://developer.wordpress.org/plugins/wordpress-org/how-your-readme-txt-works/\">arquivo readme do seu plugin</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Se encontrar problemas de compatibilidade, publique informações detalhadas no <a href=\"https://wordpress.org/support/forum/alphabeta/\">fórum de suporte</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Teste nas suas plataformas de hospedagem</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Os provedores de hospedagem oferecem a infraestrutura essencial para dar suporte ao WordPress e a quem o utiliza. Os testes em sistemas de hospedagem ajudam a orientar o processo de desenvolvimento e garantem que o WordPress e as plataformas sejam totalmente compatíveis, funcionem sem erros, sejam otimizados para oferecer a melhor experiência possível e recebam atualizações nos sites dos clientes sem problemas.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Quer testar o WordPress no seu sistema de hospedagem? <a href=\"https://make.wordpress.org/hosting/test-results-getting-started/\">Comece a configurar testes distribuídos de hospedagem</a>. Agradecemos a todas as <a href=\"https://make.wordpress.org/hosting/test-results/\">empresas de hospedagem que ajudam a testar o WordPress</a>!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Quer saber mais sobre como testar lançamentos? Acompanhe as <a href=\"https://make.wordpress.org/test/\">iniciativas de testes no Make Core</a> e participe do <a href=\"https://wordpress.slack.com/messages/core-test/\">canal #core-test</a> no <a href=\"https://wordpress.slack.com/\">Slack do Making WordPress</a>.</p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Agradecemos a <a href=\"https://profiles.wordpress.org/audrasjb/\">@audrasjb</a>, <a href=\"https://profiles.wordpress.org/r1k0/\">@r1k0</a> e <a href=\"https://profiles.wordpress.org/courane01/\">@courane01</a> pela colaboração e revisão no <a href=\"https://wordpress.org/news/2026/11/wordpress-7-2-release-candidate-1/\">post original</a>.</em></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"3765\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"WordPress 7.2 Beta 5\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"https://br.wordpress.org/2026/11/10/wordpress-7-2-beta-5/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 10 Nov 2026 17:23:12 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:12:\"Lançamentos\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:3:\"7.2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://br.wordpress.org/?p=3762\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:335:\"O WordPress 7.2 Beta 5 já está disponível para baixar e testar! Esta versão beta destina-se somente a testes e desenvolvimento. Não instale, execute nem teste esta versão do WordPress em sites de produção ou essenciais para a operação. Em vez disso, use um ambiente de testes ou um site local para explorar os novos [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"Andre\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:7775:\"\n<p class=\"wp-block-paragraph\">O WordPress 7.2 Beta 5 já está disponível para baixar e testar!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Esta versão beta destina-se somente a testes e desenvolvimento.</strong> Não instale, execute nem teste esta versão do WordPress em sites de produção ou essenciais para a operação. Em vez disso, use um ambiente de testes ou um site local para explorar os novos recursos.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Como testar o WordPress 7.2 Beta 5</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Você pode testar o WordPress 7.2 Beta 5 de qualquer uma destas formas:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><thead><tr><th>Método</th><th>Instruções</th></tr></thead><tbody><tr><td><strong>Plugin WordPress Beta Tester</strong></td><td>Instale e ative o plugin <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\">WordPress Beta Tester</a> em uma instalação do WordPress. Selecione o canal “Bleeding edge” e o fluxo “Beta/RC Only”.</td></tr><tr><td><strong>Baixe diretamente</strong></td><td>Baixe a <a href=\"https://wordpress.org/wordpress-7.2-beta5.zip\">versão Beta 5 (zip)</a> e instale-a em um site WordPress.</td></tr><tr><td><strong>Linha de comando (WP-CLI)</strong></td><td>Use este comando do <a href=\"https://make.wordpress.org/cli/\">WP-CLI</a>:<br><code>wp core update --version=7.2-beta5</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use uma <a href=\"https://playground.wordpress.net/release\">instância do WordPress Playground com a versão 7.2 Beta 5</a> para testar o software diretamente no seu navegador. Não é preciso configurar nada: basta clicar e testar!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">A data prevista para o lançamento final do WordPress 7.2 é <strong>8 de dezembro de 2026</strong>. Confira o <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\">cronograma completo de lançamento</a>. Sua ajuda para testar as versões Beta e RC é essencial para tornar este lançamento o mais estável e poderoso possível. Agradecemos a todas as pessoas que contribuem com os testes!</p>\n\n\n\n<h2 class=\"wp-block-heading\">O que há no WordPress 7.2 Beta 5?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Para ver detalhes técnicos sobre os problemas corrigidos desde a Beta 4, consulte os links a seguir:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://core.trac.wordpress.org/query?status=closed&amp;changetime=11%2F03%2F2026..11%2F10%2F2026&amp;milestone=7.2&amp;group=component&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority&amp;order=id\">Tíquetes fechados do Trac do WordPress Core</a> desde 3 de novembro de 2026.</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.2?since=2026-11-03&amp;until=2026-11-10\">Tíquetes do Gutenberg para a versão 7.2</a> desde 3 de novembro de 2026.</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">Melhorias contínuas no WordPress 7.2</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 Beta 5 continua refinando o próximo lançamento, com melhorias adicionais de segurança, acessibilidade e compatibilidade.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Entre as mudanças recentes estão as notificações por e-mail quando senhas de aplicação são criadas, a navegação pelo teclado aprimorada na barra de administração do WordPress e melhorias de acessibilidade no histórico visual. Outras correções reforçam as permissões para reações às notas, melhoram a compatibilidade com envio de arquivos MP3 e corrigem o comportamento das atualizações automáticas em instalações que usam Git worktrees.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://core.trac.wordpress.org/ticket/63927\">#63927</a>, <a href=\"https://core.trac.wordpress.org/ticket/66331\">#66331</a>, <a href=\"https://core.trac.wordpress.org/ticket/65122\">#65122</a>, <a href=\"https://core.trac.wordpress.org/ticket/66447\">#66447</a>, <a href=\"https://core.trac.wordpress.org/ticket/46544\">#46544</a>, <a href=\"https://core.trac.wordpress.org/ticket/66460\">#66460</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Mais refinamentos no Ipsum</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O novo tema padrão, Ipsum, recebe mais uma rodada de melhorias no WordPress 7.2 Beta 5. Entre os avanços de acessibilidade estão indicadores de foco do teclado aprimorados e transições de visualização que respeitam as preferências de movimento reduzido. Outros refinamentos nos estilos e padrões de blocos oferecem mais flexibilidade de design, enquanto folhas de estilo otimizadas e melhorias internas ajudam a preparar o tema para seu lançamento final.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66631\">#66631</a>, <a href=\"https://github.com/WordPress/ipsum/pull/198\">#198</a>, <a href=\"https://github.com/WordPress/ipsum/pull/187\">#187</a>, <a href=\"https://github.com/WordPress/ipsum/pull/180\">#180</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Melhorias de compatibilidade com PHP 8.6</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 pretende oferecer suporte completo ao PHP 8.6, cujo lançamento está previsto para 19 de novembro de 2026. O projeto WordPress tem um longo histórico de compatibilidade com novas versões do PHP o mais rápido possível, e este lançamento não será diferente.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Com o lançamento da Beta 5, todos os problemas conhecidos de compatibilidade com o PHP 8.6 foram resolvidos.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Embora todos os problemas conhecidos no WordPress tenham sido corrigidos, você precisará verificar se seus plugins e temas também são compatíveis com o PHP 8.6 antes de atualizar. Acompanhe o blog Making WordPress Core nos próximos dias para encontrar mais informações sobre o que verificar.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress continua incentivando todas as pessoas a usar as versões mais recentes do PHP.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66648\">#66648</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Qual é a importância dos testes?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Testar para encontrar problemas é uma parte essencial do desenvolvimento de qualquer software e uma forma significativa de contribuir, tenha você experiência ou não. <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\">Veja aqui os detalhes sobre o que testar no WordPress 7.2</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Se encontrar um problema, compartilhe-o na <a href=\"https://wordpress.org/support/forum/alphabeta/\">área Alpha/Beta</a> dos fóruns de suporte. Se você se sentir à vontade para enviar um relato de erro reproduzível, poderá fazê-lo <a href=\"https://core.trac.wordpress.org/newticket\">pelo WordPress Trac</a>. Você também pode verificar se o problema está nesta lista de <a href=\"https://core.trac.wordpress.org/tickets/major\">erros conhecidos</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Quer saber mais sobre testes de versões e como começar? Acompanhe as <a href=\"https://make.wordpress.org/test/\">iniciativas de testes no Make Core</a> e participe do <a href=\"https://wordpress.slack.com/messages/core-test/\">canal #core-test</a> no <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Agradecemos a <a href=\"https://profiles.wordpress.org/audrasjb/\">@audrasjb</a> e <a href=\"https://profiles.wordpress.org/desrosj/\">@desrosj</a> pela revisão antes da publicação no <a href=\"https://wordpress.org/news/2026/11/wordpress-7-2-beta-5/\">post original</a>.</em></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"3762\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"WordPress 7.2 Beta 4\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"https://br.wordpress.org/2026/11/03/wordpress-7-2-beta-4/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 03 Nov 2026 17:24:06 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:12:\"Lançamentos\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:3:\"7.2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://br.wordpress.org/?p=3759\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:330:\"O WordPress 7.2 Beta 4 está pronto para baixar e testar! Esta versão beta destina-se apenas a testes e desenvolvimento. Não instale, execute ou teste esta versão do WordPress em sites de produção ou de missão crítica. Em vez disso, use um ambiente de teste ou local para explorar os novos recursos. Espera, o que [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"Andre\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:7880:\"\n<p class=\"wp-block-paragraph\">O WordPress 7.2 Beta 4 está pronto para baixar e testar!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Esta versão beta destina-se</strong> <strong>apenas</strong> <strong>a testes e desenvolvimento</strong>. Não instale, execute ou teste esta versão do WordPress em sites de produção ou de missão crítica. Em vez disso, use um ambiente de teste ou local para explorar os novos recursos.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Espera, o que aconteceu ao 7.2 Beta 3?</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://br.wordpress.org/2026/10/28/wordpress-7-1-4-atualizacao-de-seguranca/\">O WordPress 7.1.4 foi lançado em 28 de outubro</a>, que incluiu o WordPress 7.2 Beta 3.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Como testar o WordPress 7.2 Beta 4</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Você pode testar o WordPress 7.2 Beta 4 de qualquer uma das seguintes maneiras:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>Pugin WordPress Beta Tester</strong></td><td>Instale e ative o plugin <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noopener\" target=\"_blank\">WordPress Beta Tester</a> em uma instalação do WordPress. Selecione o canal “Bleeding edge” e “Beta/RC Only”.</td></tr><tr><td><strong>Baixe diretamente</strong></td><td>Baixe a <a href=\"https://wordpress.org/wordpress-7.2-beta4.zip\">versão Beta 4 (zip)</a> e instale-a em um site WordPress.</td></tr><tr><td><strong>Linha de Comando (WP-CLI)</strong></td><td>Use este comando do <a href=\"https://make.wordpress.org/cli/\" rel=\"noopener\" target=\"_blank\">WP-CLI</a>:<br><code>wp core update --version=7.2-beta4</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use uma <a href=\"https://playground.wordpress.net/release\" rel=\"noopener\" target=\"_blank\">instância do WordPress Playground 7.2 Beta 4</a> para testar o software diretamente no seu navegador. Nenhuma configuração é necessária, apenas clique e teste!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">A data de lançamento final programada para o WordPress 7.2 é <strong>8 de dezembro de 2026</strong>. O cronograma de lançamento completo <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\">pode ser encontrado aqui</a>. Sua ajuda para testar versões Beta e RC é vital para tornar esta versão o mais estável e poderosa possível. Agradecemos a todos que contribuem testando!</p>\n\n\n\n<h2 class=\"wp-block-heading\">O que há no WordPress 7.2 Beta 4?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Para detalhes técnicos sobre as questões abordadas desde a versâo Beta 2, consulte os seguintes links:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://core.trac.wordpress.org/query?status=closed&amp;changetime=10%2F27%2F2026..11%2F03%2F2026&amp;milestone=7.2&amp;group=component&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority&amp;order=id\">Tíquetes fechados do Trac</a> desde 27 de outubro de 2026.</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.2?since=2026-10-27&amp;until=2026-11-03\">Tĩquetes do Gutenberg</a> desde 27 de outubro de 2026.</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">Melhorias contínuas no WordPress 7.2</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 Beta 4 continua refinando a próxima versão com melhorias na acessibilidade, confiabilidade do editor e APIs de desenvolvedores, juntamente com correções de erros e atualizações de compatibilidade adicionais.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O trabalho recente inclui melhor visibilidade do foco do teclado no modo Windows High Contrast, refinamentos para interfaces de administração e correções para alinhamento de blocos da direita para a esquerda e espaçamento de bloco personalizado.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Os desenvolvedores também se beneficiarão de melhorias contínuas na API de Habilidades, extensibilidade de DataViews e comportamento da API REST. Correções adicionais fortalecem o manuseio de revisões, a validação de entrada e a compatibilidade em ambientes suportados.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://core.trac.wordpress.org/ticket/45910\">#45910</a>, <a href=\"https://core.trac.wordpress.org/ticket/66382\">#66382</a>, <a href=\"https://core.trac.wordpress.org/ticket/66427\">#66427</a>, <a href=\"https://core.trac.wordpress.org/ticket/66383\">#66383</a>, <a href=\"https://core.trac.wordpress.org/ticket/66343\">#66343</a> e <a href=\"https://core.trac.wordpress.org/ticket/66329\">#66329</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Melhorias contínuas no Ipsum</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O novo tema padrão, Ipsum, continua a receber refinamentos antes do lançamento final do WordPress 7.2. Atualizações recentes melhoram a acessibilidade com indicadores de foco de teclado mais claros, links de leitor de tela mais descritivos e melhor suporte para idiomas da direita para a esquerda. Melhorias adicionais refinam padrões de bloqueio, espaçamento com o alvo de toque e compatibilidade de paleta de cores com outros temas padrão.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66352\">#66352</a> e <a href=\"https://github.com/WordPress/wordpress-develop/pull/15113\">#15113</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Gerenciamento de atualização de tradução aprimorada</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 facilita o gerenciamento de atualizações de tradução, exibindo atualizações individuais disponíveis na tela de atualizações. Os administradores agora podem revisar e instalar seletivamente atualizações de tradução, alinhando o gerenciamento de idiomas com a experiência familiar de atualização de plugins e temas.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://core.trac.wordpress.org/ticket/42281\">#42281</a> e <a href=\"https://github.com/WordPress/wordpress-develop/pull/11610\">#11610</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Qual a importância dos testes?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">O teste de erros é uma parte crítica do desenvolvimento de qualquer software, e é uma maneira significativa de qualquer pessoa contribuir, se você tem ou não experiência. <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\">Detalhes sobre o que testar no WordPress 7.2 estão disponíveis aqui</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Se você encontrar um problema, por favor, compartilhe-o na <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">área Alfa / Beta</a> dos fóruns de suporte. Se você está confortável em enviar um relatório de erros reproduzível, você pode fazê-lo <a href=\"https://core.trac.wordpress.org/newticket\" rel=\"noopener\" target=\"_blank\">via WordPress Trac</a>. Você também pode verificar seu problema contra essa lista de <a href=\"https://core.trac.wordpress.org/tickets/major\" rel=\"noopener\" target=\"_blank\">erros conhecidos</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curioso sobre testes de lançamentos em geral e como começar? Acompanhe as <a href=\"https://make.wordpress.org/test/\">iniciativas de teste no Make Core</a> e junte-se ao <a href=\"https://wordpress.slack.com/messages/core-test/\">canal #core-test</a> no <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Agradecemos a <a href=\"https://profiles.wordpress.org/audrasjb/\">@ audrasjb</a>, <a href=\"https://profiles.wordpress.org/courane01/\">@ courane01</a> e <a href=\"https://profiles.wordpress.org/huzaifaalmesbah/\">@ huzaifaalmesbah</a> </em>pelo <a href=\"https://wordpress.org/news/2026/11/wordpress-7-2-beta-4/\">post original</a>.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"3759\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"WordPress 7.1.4 – Atualização de Segurança\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:77:\"https://br.wordpress.org/2026/10/28/wordpress-7-1-4-atualizacao-de-seguranca/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 28 Oct 2026 18:00:39 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:12:\"Lançamentos\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:3:\"7.1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://br.wordpress.org/?p=3753\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:405:\"Esta versão de segurança apresenta correções para vários problemas. Como este é um lançamento de segurança, é recomendável que você atualize seus sites imediatamente. Você pode baixar o WordPress 7.1.4 do WordPress.org, ou visitar seu Painel do WordPress, clicar em “Atualizações” e, em seguida, clicar em “Atualizar agora”. Se você tiver sites que suportam atualizações [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"Andre\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:6261:\"\n<p class=\"wp-block-paragraph\">Esta versão de segurança apresenta correções para vários problemas.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Como este é um lançamento de segurança, é recomendável que você atualize seus sites imediatamente.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Você pode <a href=\"https://wordpress.org/download/\">baixar o WordPress 7.1.4 do WordPress.org</a>, ou visitar seu Painel do WordPress, clicar em “Atualizações” e, em seguida, clicar em “Atualizar agora”. Se você tiver sites que suportam atualizações automáticas em segundo plano, o processo de atualização começará automaticamente.<br>WordPress 7.1.4 é uma versão de ciclo curto. O próximo grande lançamento será a <a href=\"https://make.wordpress.org/core/7-2/\">versão 7.2</a>, atualmente prevista para o dia <strong>8 de dezembro</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Para mais informações, visite o <a href=\"https://wordpress.org/documentation/wordpress-version/version-7-1-4/\">site do WordPress 7.1.4 HelpHub</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Atualizações de segurança incluídas nesta versão</h2>\n\n\n\n<p class=\"wp-block-paragraph\">A equipe de segurança gostaria de agradecer às seguintes pessoas e organizações por relatarem vulnerabilidades de forma responsável e permitirem que elas sejam corrigidas nesta versão:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Uma vulnerabilidade no processo de atualização do WordPress que pode levar à execução remota de código durante a janela de atualização, relatada por <a href=\"https://www.picussecurity.com/resource/author/umut-bayram\">Umut Bayram</a>.</li>\n\n\n\n<li>Um XSS armazenado com marcação de bloco, relatado por <a href=\"https://www.linkedin.com/in/rafiemuhammad/\">Rafie Muhammad</a> (Awesome Motive, Inc.).</li>\n\n\n\n<li>Solicitações de Remoção de Dados de Privacidade podem ser criadas de forma a levar a ataques de XSS, relatado pela Anthropic.</li>\n\n\n\n<li>Vários problemas XSS armazenados na API de Interatividade descobertos de forma independente por AnC e DatNLQ do VietSunshine Cyber Security, rekter0 e Anas cherni, <a href=\"https://decentsecurity.io/\">Marcel Karlsson</a> (whoismarcel) e Weston Ruter, Jon Surrell, Alex Concha e Luis Herranz da Equipe de Segurança do WordPress.</li>\n\n\n\n<li>Um problema de negação de serviço armazenado na API de Interatividade, relatado por Jon Surrell da Equipe de Segurança do WordPress.</li>\n\n\n\n<li>Um XSS armazenado no Personalizar, relatado por <a href=\"https://www.linkedin.com/in/rafiemuhammad/\">Rafie Muhammad</a> (Awesome Motive, Inc.).</li>\n\n\n\n<li>Um XSS armazenado no bloco Categorias relatado por Ben Bidner da Equipe de Segurança do WordPress.</li>\n\n\n\n<li>Alguns logins de usuário criados podem levar a um ataque XSS relatado pela Anthropic.</li>\n\n\n\n<li>Os conjuntos de alterações do Personalizar não publicados podem ser descobertos por usuários não autenticados, relatados por <a href=\"https://www.linkedin.com/in/antoniolorensius/\">Antonio Lorensius Silaban</a>.</li>\n\n\n\n<li>Um XSS armazenado em Playlist e blocos de imagem, relatado por Ben Bidner da Equipe de Segurança do WordPress.</li>\n\n\n\n<li>Um XSS nos blocos <code>core/comments-pagination-next </code>e <code>core/comments-pagination-previous</code>, relatados por Alex Concha da Equipe de Segurança do WordPress.</li>\n\n\n\n<li>As notas podem ser lidas por usuários privilegiados, mas que não têm acesso para editar o post a que a nota está anexada, relatada por Ramon da Equipe de Segurança do WordPress.</li>\n\n\n\n<li>Uma atualização para os certificados de raiz agrupados devido à revogação do eMudhra.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Agradecimento aos colaboradores do WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Este lançamento foi liderado por <a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a> e <a href=\"https://profiles.wordpress.org/ntsekouras/\">Nik Tsekouras</a>. O WordPress 7.1.4 não teria sido possível sem as contribuições das seguintes pessoas:</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://w.org/@jorbin\">Aaron Jorbin</a>, <a href=\"https://w.org/@adamsilverstein\">Adam Silverstein</a>, <a href=\"https://w.org/@xknown\">Alex Concha</a>, <a href=\"https://w.org/@aduth\">Andrew Duthie</a>, <a href=\"https://w.org/@andrewserong\">Andrew Serong</a>, <a href=\"https://w.org/@darerodz\">David Arenas</a>, <a href=\"https://w.org/@dmsnell\">Dennis Snell</a>, <a href=\"https://w.org/@ellatrix\">Ella Van Durpe</a>, <a href=\"https://w.org/@mamaduka\">George Mamadashvili</a>, <a href=\"https://w.org/@isabel_brison\">Isabel Brison</a>, <a href=\"https://w.org/@whyisjake\">Jake Spurlock</a>, <a href=\"https://w.org/@audrasjb\">Jb Audras</a>, <a href=\"https://w.org/@jeremyfelt\">Jeremy Felt</a>, <a href=\"https://w.org/@johnbillion\">John Blackbourn</a>, <a href=\"https://w.org/@jonsurrell\">Jon Surrell</a>, <a href=\"https://w.org/@desrosj\">Jonathan Desrosiers</a>, <a href=\"https://profiles.wordpress.org/kirasong/\">Kira Song,</a><a href=\"https://w.org/@lancewillett\">Lance Willett</a>, <a href=\"https://w.org/@luisherranz\">luisherranz</a>, <a href=\"https://w.org/@mciampini\">Marco Ciampini</a>, <a href=\"https://w.org/@marcs0h\">marcs0h</a>, <a href=\"https://w.org/@tyxla\">Marin Atanasov</a>, <a href=\"https://w.org/@santosguillamot\">Mario Santos</a>, <a href=\"https://w.org/@mcsf\">Miguel Fonseca</a>, <a href=\"https://w.org/@ntsekouras\">Nik Tsekouras</a>, <a href=\"https://w.org/@peterwilsoncc\">Peter Wilson</a>, <a href=\"https://w.org/@ramonopoly\">ramonopoly</a>, <a href=\"https://w.org/@rfaile313\">Rudy Faile</a>, <a href=\"https://w.org/@umut3806\">umut3806</a> e <a href=\"https://w.org/@westonruter\">Weston Ruter</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Como cortesia, as correções de segurança foram retroportadas para todas as versões elegíveis para receber correções de segurança (atualmente até 4.7). Como lembrete, <strong>apenas a versão mais recente do WordPress é ativamente suportada</strong>. Os backports estão em andamento e serão enviados à medida que se tornam prontos.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 Beta 3 também foi lançado, contendo todas as correções aplicáveis.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"3753\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"WordPress 7.2 Beta 2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"https://br.wordpress.org/2026/10/27/wordpress-7-2-beta-2/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 27 Oct 2026 16:42:09 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:12:\"Lançamentos\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:3:\"7.2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://br.wordpress.org/?p=3749\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:330:\"O WordPress 7.2 Beta 2 está pronto para baixar e testar! Esta versão beta destina-se apenas a testes e desenvolvimento. Não instale, execute ou teste esta versão do WordPress em sites de produção ou de missão crítica. Em vez disso, use um ambiente de teste ou local para explorar os novos recursos. Como testar o [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"Andre\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:6099:\"\n<p class=\"wp-block-paragraph\">O WordPress 7.2 Beta 2 está pronto para baixar e testar!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Esta versão beta destina-se apenas a testes e desenvolvimento</strong>. Não instale, execute ou teste esta versão do WordPress em sites de produção ou de missão crítica. Em vez disso, use um ambiente de teste ou local para explorar os novos recursos.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Como testar o WordPress 7.2 Beta 2</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Você pode testar o WordPress 7.2 Beta 2 de qualquer uma das seguintes maneiras:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>Plugin WordPress Beta Tester</strong></td><td>Instale e ative o plugin <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noopener\" target=\"_blank\">WordPress Beta Tester</a> em uma instalação do WordPress. Selecione o canal “Bleeding edge” e “Beta/RC Only”.</td></tr><tr><td><strong>Baixe diretamente</strong></td><td>Baixe a <a href=\"https://wordpress.org/wordpress-7.2-beta2.zip\">versão Beta 2 (zip)</a> e instale-a em um site WordPress.</td></tr><tr><td><strong>Linha de Comando (WP-CLI)</strong></td><td>Use este comando do <a href=\"https://make.wordpress.org/cli/\" rel=\"noopener\" target=\"_blank\">WP-CLI</a>:<br><code>wp core update --version=7.2-beta2</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use uma <a href=\"https://playground.wordpress.net/?site-slug=kind-classic-mountain&amp;networking=no&amp;php=8.3&amp;wp=beta&amp;language=&amp;multisite=no\" rel=\"noopener\" target=\"_blank\">instância do WordPress Playground do WordPress 7.2 Beta 2</a> para testar o software diretamente no seu navegador. Nenhuma configuração é necessária, apenas clique e testar!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">A data de lançamento final programada para o WordPress 7.2 é <strong>8 de dezembro de 2026</strong>. O cronograma de lançamento completo <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\">pode ser encontrado aqui</a>. Sua ajuda para testar versões Beta e RC é vital para tornar esta versão o mais estável e poderosa possível. Agradecemos a todos que contribuem testando!</p>\n\n\n\n<h2 class=\"wp-block-heading\">O que há no WordPress 7.2 Beta 2?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Para detalhes técnicos sobre as questões abordadas desde a versão Beta 1, consulte os seguintes links:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://core.trac.wordpress.org/query?status=closed&amp;changetime=10%2F21%2F2026..10%2F28%2F2026&amp;milestone=7.2&amp;group=component&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority&amp;order=id\">Tiquetes fechados no Trac para a versão Beta 2</a> desde 20 de outubro de 2026.</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.2?since=2026-10-21&amp;until=2026-10-28\">Tíquetes do Gutenberg para a versão Beta 2</a> desde 20 de outubro de 2026.</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">Melhorias contínuas no WordPress 7.2</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 Beta 2 é baseado no primeiro beta com aprimoramentos adicionais, correções de erros, refinamentos na experiência de administração e nas APIs de desenvolvedores.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O desenvolvimento continua na <strong>API de Habilidades</strong>, incluindo consulta de conteúdo, requisitos de permissões e melhorias no manuseio e permissões de esquemas. Novos recursos de registro do lado do servidor para <strong>DataViews e DataForm</strong> também fornecem aos desenvolvedores mais maneiras de estender as interfaces do WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O trabalho adicional inclui melhorias na flexibilidade da API REST, no carregamento de ativos de administração e na transição para os ícones SVG modernos em toda a administração do WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66268\">#66268</a>, <a href=\"https://core.trac.wordpress.org/ticket/66325\">#66325</a>, <a href=\"https://core.trac.wordpress.org/ticket/66229\">#66229</a>, <a href=\"https://core.trac.wordpress.org/ticket/66343\">#66343</a>, <a href=\"https://core.trac.wordpress.org/ticket/57548\">#57548</a> e <a href=\"https://core.trac.wordpress.org/ticket/65089\">#65089</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Qual a importância dos teste?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">O teste para erros é uma parte crítica do desenvolvimento de qualquer software, e é uma maneira significativa de qualquer pessoa contribuir – se você tem ou não experiência. Veja mais <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\">detalhes sobre o que testar no WordPress 7.2, disponíveis aqui</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Se você encontrar um problema, compartilhe-o na <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">área Alfa / Beta</a> dos fóruns de suporte. Se você está confortável em enviar um relatório de erros reproduzível, você pode fazê-lo <a href=\"https://core.trac.wordpress.org/newticket\" rel=\"noopener\" target=\"_blank\">via WordPress Trac</a>. Você também pode verificar seu problema se encontra nesta lista de <a href=\"https://core.trac.wordpress.org/tickets/major\" rel=\"noopener\" target=\"_blank\">erros conhecidos</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curioso sobre testes de lançamentos em geral e como começar? Acompanhe as <a href=\"https://make.wordpress.org/test/\">iniciativas de teste no Make Core</a> e junte-se ao <a href=\"https://wordpress.slack.com/messages/core-test/\">canal #core-test</a> no <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Agradecemos a <a href=\"https://profiles.wordpress.org/mamaduka/\">@mamaduka</a> pela revisão do <a href=\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-2/\">post original</a>.</em></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"3749\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:44:\"Atualização crítica de  segurança do PHP\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:76:\"https://br.wordpress.org/2026/10/21/atualizacao-critica-de-seguranca-do-php/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 21 Oct 2026 14:26:33 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Segurança\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://br.wordpress.org/?p=3746\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:380:\"O projeto PHP anunciou uma versão de segurança que corrige duas vulnerabilidades de segurança críticas descobertas no PHP. Devido à gravidade crítica, os proprietários de sites são encorajados a atualizar imediatamente suas instalações do PHP. Sua hospedagem pode já estar trabalhando para atualizar o PHP e colocar as regras do firewall de aplicativos da Web [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"Andre\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2664:\"\n<p class=\"wp-block-paragraph\"><a href=\"https://www.php.net/archive/2026.php#2026-10-21-5\">O projeto PHP anunciou uma versão de segurança que corrige duas vulnerabilidades de segurança críticas descobertas no PHP</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Devido à gravidade crítica, os proprietários de sites são encorajados a atualizar imediatamente suas instalações do PHP. Sua hospedagem pode já estar trabalhando para atualizar o PHP e colocar as regras do firewall de aplicativos da Web (WAF) em vigor para mitigar as vulnerabilidades, mas você ainda deve verificar se há atualizações de sua hospedagem e, se necessário, atualizar o PHP o mais rápido possível.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Dentro do WordPress, você pode ver qual versão do PHP seu site executa em <code>Ferramentas &gt; Diagnóstico &gt; Informações -&gt; Servidor</code>. Muitas hospedagens fornecem essas informações também em seu painel de administração.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Essas vulnerabilidades <em>não</em> são específicas do WordPress e afetam qualquer servidor que hospede um aplicativo PHP. Nenhuma atualização do WordPress é necessária ou planejada para esses problemas.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Versões do PHP anteriores ao 8.2 não recebem mais atualizações de segurança do projeto PHP.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Se o seu site executa uma versão anterior e você gerencia sua própria hospedagem web, você deve <em>considerar deixar seu servidor offline</em> enquanto se prepara para atualizar para uma versão mais recente do PHP. Este conselho está sendo publicado por várias agências nacionais de segurança cibernética. Para citar o <a href=\"https://www.ncsc.gov.uk/news/critical-security-issue-affecting-php\">Centro Nacional de Segurança Cibernética do Reino Unido</a>:</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">Quando a remediação imediata não for viável, as organizações devem considerar deixar o sistema offline até que ele possa ser totalmente mitigado.</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">Mais informações sobre wordpress.org:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://wordpress.org/support/update-php/\">Obtenha um site mais rápido e seguro: atualize o PHP hoje</a></li>\n\n\n\n<li><a href=\"https://make.wordpress.org/core/handbook/references/php-compatibility-and-wordpress-versions/\">Compatibilidade PHP e versões do WordPress</a></li>\n\n\n\n<li><a href=\"https://wordpress.org/documentation/article/faq-my-site-was-hacked/\">FAQ Meu site foi hackeado</a></li>\n</ul>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"3746\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"WordPress 7.2 Beta 1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"https://br.wordpress.org/2026/10/20/wordpress-7-2-beta-1/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 20 Oct 2026 16:58:54 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:12:\"Lançamentos\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:3:\"7.2\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://br.wordpress.org/?p=3740\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:331:\"Esta versão beta destina-se apenas a testes e desenvolvimento. Não instale, execute ou teste esta versão do WordPress em sites de produção ou de missão crítica. Em vez disso, use um ambiente de teste ou local para explorar os novos recursos. Como testar Você pode testar o WordPress 7.2 Beta 1 de qualquer uma das [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"Andre\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:17854:\"\n<p class=\"wp-block-paragraph\"><strong>Esta versão beta destina-se</strong> <strong>apenas</strong> <strong>a testes e desenvolvimento</strong>. Não instale, execute ou teste esta versão do WordPress em sites de produção ou de missão crítica. Em vez disso, use um ambiente de teste ou local para explorar os novos recursos.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Como testar</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Você pode testar o WordPress 7.2 Beta 1 de qualquer uma das seguintes maneiras:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>Plugin</strong> <strong>WordPress Beta Tester</strong></td><td>Instale e ative o plugin <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noopener\" target=\"_blank\">WordPress Beta Tester</a> em uma instalação do WordPress. Selecione o canal “Bleeding edge” e “Beta/RC Only”.</td></tr><tr><td><strong>Baixe diretamente</strong></td><td>Baixe a <a href=\"https://wordpress.org/wordpress-7.2-beta1.zip\">versão 7.2 Beta 1 (zip)</a> e instale-a em um site WordPress.</td></tr><tr><td><strong>Linha de Comando (WP-CLI)</strong></td><td>Use este comando do <a href=\"https://make.wordpress.org/cli/\" rel=\"noopener\" target=\"_blank\">WP-CLI</a>:<br><code>wp core update --version=7.2-beta1</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use uma <a href=\"https://playground.wordpress.net/?site-slug=kind-classic-mountain&amp;networking=no&amp;php=8.3&amp;wp=beta&amp;language=&amp;multisite=no\" rel=\"noopener\" target=\"_blank\">instância do WordPress 7.2 Beta 1</a> para testar o software diretamente no seu navegador. Nenhuma configuração necessária-apenas clique e use!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">A data de lançamento final programada para o WordPress 7.2 é <strong>8 de dezembro de 2026</strong>. O <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\" rel=\"noopener\" target=\"_blank\">cronograma de lançamento completo pode ser encontrado aqui</a>. Sua ajuda para testar versões Beta e RC é vital para tornar esta versão o mais estável e poderosa possível. Agradecemos a todos que contribuem testando!</p>\n\n\n\n<h2 class=\"wp-block-heading\">Experiência de Edição</h2>\n\n\n\n<h3 class=\"wp-block-heading\">Controles de Design Responsivo</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Com base nas melhorias de design responsivas introduzidas no WordPress 7.1, o WordPress 7.2 expande o estilo específico da janela para ferramentas e blocos de design adicionais. Os criadores obtêm um controle mais granular sobre como os layouts e as configurações visuais se adaptam em todos os tamanhos de tela, incluindo configurações responsivas da galeria para colunas, corte de imagens e proporções.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/80388\">#80388</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/82003\">#82003</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Estilos globais e ferramentas de design aprimorados</h3>\n\n\n\n<figure class=\"wp-block-image is-resized\"><img decoding=\"async\" alt=\"\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global-1.webp?resize=1024%2C576&amp;ssl=1\" style=\"aspect-ratio:1.7777777777777777;width:1024px;height:auto\"></figure>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 torna o estilo em todo o site mais fácil de gerenciar com um novo filtro <em>personalizado</em> para encontrar blocos com estilos modificados e valores de estilos globais herdados exibidos diretamente nos controles do inspetor de blocos. Ferramentas de design expandidas e suporte para elementos de formulário de estilo fornecem flexibilidade adicional ao criar uma identidade visual consistente em um site.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/82520\">#82520</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/76525\">#76525</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/34198\">#34198</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84657\">#84657</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Suporte de Sombra de Texto</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 apresenta novos controles de sombra de texto, dando aos criadores mais maneiras de adicionar profundidade e ênfase ao seu conteúdo. As sombras de texto podem ser personalizadas através de configurações de bloco e definidas como predefinições em <code>theme.json</code>, tornando mais fácil manter a tipografia consistente em um site.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://github.com/WordPress/gutenberg/pull/73320\">#73320</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/79584\">#79584</a>, <a href=\"https://core.trac.wordpress.org/ticket/65869\">#65869</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Gestão de navegação mais fácil</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Melhorias no editor do site tornam o gerenciamento de links de navegação mais intuitivo. Os criadores podem adicionar, organizar e editar itens de navegação diretamente da barra lateral do editor, facilitando a manutenção de menus do site sem interromper o fluxo de trabalho de edição.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/77069\">#77069</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Melhor colaboração com notas</h3>\n\n\n\n<figure class=\"wp-block-image is-resized\"><img decoding=\"async\" alt=\"\" class=\"wp-image-21820\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Emojis-in-Notes.webp?resize=1024%2C576&amp;ssl=1\" style=\"aspect-ratio:1.7777777777777777;width:1024px;height:auto\"></figure>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 apresenta reações de Emoji em notas e um novo ícone de barra de ferramentas que facilita o acesso e o gerenciamento. As notas são transferidas para a tela do editor, trazendo conversas diretamente para a margem. Os usuários agora podem manter as notas e a barra lateral de configurações de bloco abertas simultaneamente, facilitando a avaliação e feedback durante a edição de conteúdo.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Um novo modo de anotações minimizado reduz a desordem visual, enquanto melhorias no posicionamento e na exibição criam uma experiência de colaboração mais suave e consistente.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/79970\">#79970</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/83786\">#83786</a>, <a href=\"https://github.com/WordPress/gutenberg/issues/80015\">#80015</a>, <a href=\"https://core.trac.wordpress.org/ticket/64638\">#64638</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Envios de mídias mais rápidos e eficientes</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 expande o processamento de mídia do lado do cliente para a biblioteca de mídia, permitindo que as imagens sejam redimensionadas, compactadas e convertidas diretamente no navegador antes de serem carregadas. Isso pode melhorar o desempenho do upload, reduzir o uso do recurso do servidor e fornecer melhor suporte para formatos de imagem modernos, particularmente em ambientes de hospedagem com recursos limitados de processamento de imagem.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://core.trac.wordpress.org/ticket/65661\">#65661</a>, <a href=\"https://github.com/WordPress/wordpress-develop/pull/12585\">#12585</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Novo widget de painel “Neste Dia”</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 apresenta um novo widget de painel do <strong>&#8220;Neste dia&#8221;</strong> que ajuda os usuários a redescobrir o conteúdo publicado na mesma data nos anos anteriores. Ao destacar posts do histórico do site, o widget facilita a revisitação de conteúdo passado, celebra marcos e encontra oportunidades para atualizar ou compartilhar novamente posts mais antigos.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://core.trac.wordpress.org/ticket/65116\">#65116</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Melhorias de usabilidade do editor de bloco</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 inclui uma coleção de melhorias menores destinadas a reduzir o atrito na edição diária. Essas mudanças incluem mensagens de erro mais claras, feedback mais útil quando algo dá errado e refinamentos para interações comuns com o editor, tornando a experiência de edição mais previsível e acessível.</p>\n\n\n\n<figure class=\"wp-block-image is-resized\"><img decoding=\"async\" alt=\"\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Error-message-update.webp?resize=1024%2C576&amp;ssl=1\" style=\"aspect-ratio:1.7777777777777777;width:1024px;height:auto\"></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://github.com/WordPress/gutenberg/issues/81453\">#81453</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/82496\">#82496</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84656\">#84656</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/84649\">#84649</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Uma administração mais consistente do WordPress</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 continua modernizando a experiência de administração, substituindo os Dashicons legados na barra de administração e na barra lateral por ícones da biblioteca de ícones do WordPress. Os ícones atualizados trazem maior consistência visual entre o painel tradicional do WordPress e as interfaces de edição mais recentes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://github.com/WordPress/wordpress-develop/pull/12270\">#12270</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Uma experiência de configurações de bloco atualizada</h3>\n\n\n\n<figure class=\"wp-block-image is-resized\"><img decoding=\"async\" alt=\"\" class=\"wp-image-21822\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/10/Forms-Global.webp?resize=1024%2C576&amp;ssl=1\" style=\"aspect-ratio:1.7777777777777777;width:1024px;height:auto\"></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Um novo inspetor alimentado pelo DataForm introduz uma abordagem atualizada para gerenciar as configurações de blocos no editor. Construído sobre o sistema de componentes do DataForm, este trabalho tem como objetivo fornecer controles mais consistentes e uma base mais extensível para futuras melhorias de edição de blocos.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://github.com/WordPress/gutenberg\">GitHub do Gutenberg</a> · <a href=\"https://make.wordpress.org/core/2026/09/17/call-for-testing-dataform-editor-inspector/\">Chamada para Testes</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Administração WordPress mais rápida</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 melhora o desempenho do administrador modernizando como os scripts e as folhas de estilo são carregados. Em vez de combinar ativos em arquivos grandes, o WordPress agora os carrega individualmente para um melhor cache do navegador. Um novo mecanismo de pré-busca também prevê quais telas da administração provavelmente serão visitadas em seguida, carregando seus recursos com antecedência para tornar a navegação entre o painel, as listas de posts e o editor mais rápidos.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://core.trac.wordpress.org/ticket/57548\">#57548</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Para desenvolvedores</h2>\n\n\n\n<h3 class=\"wp-block-heading\">Nova API de Credenciais</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 apresenta uma <strong>API de Credenciais</strong>, fornecendo aos desenvolvedores uma maneira padronizada e segura de armazenar credenciais confidenciais, como chaves de API e tokens de autenticação. A API suporta criptografia, rotação de credenciais e provedores de armazenamento personalizáveis, ajudando plugins e integrações a gerenciar informações confidenciais com mais segurança.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais</strong>: <a href=\"https://core.trac.wordpress.org/ticket/66187\">#66187</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Redirecionamentos de conteúdo aleatório</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 adiciona suporte para redirecionamentos de conteúdo aleatórios, permitindo que os visitantes descubram um post selecionado aleatoriamente por meio de uma URL dedicada. Isso fornece uma maneira simples de incentivar a exploração de conteúdo e ajudar os leitores a redescobrir posts mais antigos.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Saiba mais:</strong> <a href=\"https://core.trac.wordpress.org/ticket/64498\">#64498</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">APIs mais poderosas para desenvolvedores</h3>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 expande a <strong>API de Habilidades</strong> com novos recursos para acessar e consultar dados do WordPress, fornecendo uma base mais consistente para integrações, automação e ferramentas alimentadas por IA. (<a href=\"https://core.trac.wordpress.org/ticket/66268\">#66268</a>, <a href=\"https://core.trac.wordpress.org/ticket/64605\">#64605</a>, <a href=\"https://core.trac.wordpress.org/ticket/64657\">#64657</a>).</p>\n\n\n\n<p class=\"wp-block-paragraph\">Os aprimoramentos da <strong>API de Interatividade</strong> introduzem novas maneiras de renderizar HTML confiável e gerenciar a navegação reativa, dando aos desenvolvedores mais flexibilidade ao criar blocos dinâmicos e interativos. (<a href=\"https://core.trac.wordpress.org/ticket/66246\">#66246</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/83092\">#83092</a>).</p>\n\n\n\n<p class=\"wp-block-paragraph\">Melhorias adicionais na <strong>API de HTML</strong>, com suporte a blocos e ferramentas de design responsivo, fornecem processamento de marcação mais confiável e maior controle sobre como os blocos personalizados são estilizados e exibidos em todos os dispositivos. (<a href=\"https://core.trac.wordpress.org/ticket/65824\">#65824</a>, <a href=\"https://core.trac.wordpress.org/ticket/66150\">#66150</a>, <a href=\"https://core.trac.wordpress.org/ticket/65869\">#65869</a>).</p>\n\n\n\n<h2 class=\"wp-block-heading\">Qual a importância dos testes?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">O teste para erros é uma parte crítica do desenvolvimento de qualquer software, e é uma maneira significativa de qualquer pessoa contribuir – se você tem ou não experiência. Veja mais <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\">detalhes sobre o que testar no WordPress 7.2, disponíveis aqui</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Se você encontrar um problema, compartilhe-o na <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">área Alfa / Beta</a> dos fóruns de suporte. Se você está confortável em enviar um relatório de erros reproduzível, você pode fazê-lo <a href=\"https://core.trac.wordpress.org/newticket\" rel=\"noopener\" target=\"_blank\">via WordPress Trac</a>. Você também pode verificar seu problema se encontra nesta lista de <a href=\"https://core.trac.wordpress.org/tickets/major\" rel=\"noopener\" target=\"_blank\">erros conhecidos</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curioso sobre testes de lançamentos em geral e como começar? Acompanhe as <a href=\"https://make.wordpress.org/test/\">iniciativas de teste no Make Core</a> e junte-se ao <a href=\"https://wordpress.slack.com/messages/core-test/\">canal #core-test</a> no <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.2 incluirá novos recursos que anteriormente estavam disponíveis apenas no plugin Gutenberg. Saiba mais sobre as atualizações do Gutenberg desde o WordPress 7.1 nos posts do <a href=\"https://make.wordpress.org/core/tag/gutenberg-new/\">What’s New in Gutenberg</a> para as versões <a href=\"https://make.wordpress.org/core/2026/08/06/whats-new-in-gutenberg-23-7-05-august/\">23.7</a>, <a href=\"https://make.wordpress.org/core/2026/08/19/whats-new-in-gutenberg-23-8-19-august/\">23.8</a>, <a href=\"https://make.wordpress.org/core/2026/09/02/whats-new-in-gutenberg-23-9-2-september/\">23.9</a>, <a href=\"https://make.wordpress.org/core/2026/09/16/whats-new-in-gutenberg-24-0-16-september/\">24.0</a>, <a href=\"https://make.wordpress.org/core/2026/09/30/whats-new-in-gutenberg-24-1-30-september/\">24.1</a>, <a href=\"https://make.wordpress.org/core/2026/10/14/whats-new-in-gutenberg-24-2-14-october/\">24.2</a> e 24.3.</p>\n\n\n\n<h2 class=\"wp-block-heading\">O que há de novo no WordPress 7.2?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Com tanto em andamento para o WordPress 7.2 Beta 1, isso ainda é apenas o começo. Aguarde um refinamento contínuo com cada versão Beta e RC antes do lançamento final em <strong>8 de dezembro de 2026</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Agradecemos a <a href=\"https://profiles.wordpress.org/audrasjb/\">@audrasjb</a>, <a href=\"https://profiles.wordpress.org/annezazu/\">@annezazu</a>, <a href=\"https://profiles.wordpress.org/adamsilverstein/\">@adamsilverstein</a>, <a href=\"https://profiles.wordpress.org/westonruter/\">@westonruter</a>, <a href=\"https://profiles.wordpress.org/markoserb/\">@markoserb</a>, <a href=\"https://profiles.wordpress.org/im3dabasia1/\">@im3dabasia1</a>, <a href=\"https://profiles.wordpress.org/jorbin/\">@jorbin</a> e <a href=\"https://profiles.wordpress.org/noruzzaman/\">@noruzzaman</a> <em>pela colaboração no <a href=\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-1-is-ready-for-download-and-testing/\">post original</a>.</em></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"3740\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"Conheça o MCP Adapter: A ponte oficial entre o WordPress e a Inteligência Artificial\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:120:\"https://br.wordpress.org/2026/10/06/conheca-o-mcp-adapter-a-ponte-oficial-entre-o-wordpress-e-a-inteligencia-artificial/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 06 Oct 2026 19:08:22 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Lançamentos\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://br.wordpress.org/?p=3730\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:362:\"A inteligência artificial está transformando a forma como interagimos com a web, e o WordPress já está se movendo para liderar essa integração. Por isso, estamos muito empolgados em destacar o lançamento do MCP Adapter, o plugin oficial da iniciativa AI Building Blocks do WordPress. Se você gostaria que assistentes de IA, como Claude, ChatGPT [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"Andre\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:3272:\"\n<p class=\"wp-block-paragraph\">A inteligência artificial está transformando a forma como interagimos com a web, e o WordPress já está se movendo para liderar essa integração. Por isso, estamos muito empolgados em destacar o lançamento do <strong>MCP Adapter</strong>, o plugin oficial da <a href=\"https://make.wordpress.org/ai/2025/07/17/ai-building-blocks/\">iniciativa <em>AI Building Blocks</em> do WordPress</a>. Se você gostaria que assistentes de IA, como Claude, ChatGPT ou Gemini, leiam e interajam com o seu site de maneira nativa, este plugin é o ponto oficial de partida.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>O plugin MCP Adapter</strong></h2>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://br.wordpress.org/files/2026/10/mcp-adapter.png\"><img fetchpriority=\"high\" decoding=\"async\" width=\"1024\" height=\"538\" src=\"https://br.wordpress.org/files/2026/10/mcp-adapter-1024x538.png\" alt=\"\" class=\"wp-image-3731\" srcset=\"https://br.wordpress.org/files/2026/10/mcp-adapter-1024x538.png 1024w, https://br.wordpress.org/files/2026/10/mcp-adapter-300x158.png 300w, https://br.wordpress.org/files/2026/10/mcp-adapter-767x403.png 767w, https://br.wordpress.org/files/2026/10/mcp-adapter.png 1205w\" sizes=\"(max-width: 1024px) 100vw, 1024px\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">O <strong>MCP Adapter</strong> (Model Context Protocol Adapter) age como um &#8220;tradutor universal&#8221;. Em vez de exigir integrações complexas ou APIs específicas para cada novo serviço de inteligência artificial do mercado, ele conecta a <a href=\"https://developer.wordpress.org/apis/abilities-api/\"><em>Abilities API</em> do WordPress</a> diretamente com o padrão aberto do Model Context Protocol.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Na prática, ele pega as funcionalidades registradas no seu site (seja pelo<em> </em>núcleo do WordPress, tema ou por outros plugins) e as transforma em ferramentas e recursos que qualquer assistente de IA compatível com MCP pode entender e executar. Você expõe a funcionalidade uma única vez no WordPress, e o plugin MCP Adapter cuida de toda a negociação de protocolo, tratamento de erros e verificação de permissões de segurança nos bastidores.</p>\n\n\n\n<h2 class=\"wp-block-heading\"><strong>Traduzido para o <strong>português do Brasil</strong></strong></h2>\n\n\n\n<p class=\"wp-block-paragraph\">Como uma comunidade ativa e apaixonada, sabemos que a barreira do idioma nunca deve ser um obstáculo para a adoção de novas tecnologias. É por isso que temos o orgulho de destacar que o MCP Adapter já está <strong>100% traduzido para o português do Brasil</strong>!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Você pode baixar, instalar e configurar o plugin agora mesmo com uma interface totalmente no nosso idioma, garantindo que o gerenciamento de integrações seja o mais acessível possível para desenvolvedores e administradores de sites brasileiros.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Ficou curioso? Acesse a <a href=\"https://wordpress.org/plugins/mcp-adapter/\" target=\"_blank\" rel=\"noopener\">página oficial do MCP Adapter no repositório de plugins</a> para fazer o download, conferir a documentação e começar a explorar o futuro do WordPress com seu assistente de AI preferido!</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"3730\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:62:\"WordPress 7.1.3 – Atualização de manutenção e segurança\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:90:\"https://br.wordpress.org/2026/10/06/wordpress-7-1-3-atualizacao-de-manutencao-e-seguranca/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 06 Oct 2026 17:33:33 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:3:\"7.1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://br.wordpress.org/?p=3734\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:385:\"Esta versão de segurança e manutenção possui 7 correções de segurança e 4 correções de erros. Como este é um lançamento de segurança, é recomendável que você atualize seus sites imediatamente. Você pode baixar o WordPress 7.1.3 do WordPress.org ou visitar seu painel do WordPress, clicar em “Atualizações” e, em seguida, clicar em “Atualizar agora”. [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:5:\"Andre\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:5924:\"\n<p class=\"wp-block-paragraph\">Esta versão de segurança e manutenção possui <a href=\"https://core.trac.wordpress.org/query?milestone=7.1.3&amp;status=closed&amp;order=priority&amp;col=id&amp;col=summary&amp;col=status&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority\">7 correções de segurança</a> e <a href=\"https://core.trac.wordpress.org/query?milestone=7.1.3&amp;status=closed&amp;order=priority&amp;col=id&amp;col=summary&amp;col=status&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority\">4 correções de erros</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Como este é um lançamento de segurança, é recomendável que você atualize seus sites imediatamente.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Você pode <a href=\"https://wordpress.org/wordpress-7.1.3.zip\">baixar o WordPress 7.1.3 do WordPress.org</a> ou visitar seu painel do WordPress, clicar em “Atualizações” e, em seguida, clicar em “Atualizar agora”. Se você tiver sites que suportam atualizações automáticas em segundo plano, o processo de atualização começará automaticamente.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Atualizações de segurança incluídas nesta versão</h2>\n\n\n\n<p class=\"wp-block-paragraph\">A equipe de segurança gostaria de agradecer às seguintes pessoas e organizações por relatarem vulnerabilidades de forma responsável e permitirem que elas sejam corrigidas nesta versão:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Um XSS armazenado na página de administração de comentários, explorável através de comentários pendentes, relatado por <a href=\"https://trailofbits.com/\">Thomas Chauchefoin em Trail of Bits</a>.</li>\n\n\n\n<li>Uma questão DoS no método <code>WP_Http::make_absolute_url()</code>, relatado por Anthropic.</li>\n\n\n\n<li>Uma injeção SQL de segunda ordem na exportação do WordPress WXR, relatada pelo Anthropic.</li>\n\n\n\n<li>Uma fraqueza permitindo que os usuários com perfil de autor criem posts fixados, relatadas pelo Anthropic.</li>\n\n\n\n<li>Comentário não autenticados sobre posts privados, relatado por <a href=\"https://patchstack.com/\">Ananda Dhakal, do Patchstack</a></li>\n\n\n\n<li>Incorporações do Imgur vulneráveis a XSS, relatadas por <a href=\"https://jackfromeast.github.io/\">Zhengyu Liu</a>, <a href=\"https://jesse-yang.com/\">Jingcheng Yang</a> e <a href=\"https://gvzhong.github.io/\">Gavin Zhong</a>.</li>\n\n\n\n<li>Parâmetros forjáveis passados para o hook <code>{status}_{type}</code>, que podem levar à colisão de nomes, relatado por Alex Concha da equipe de segurança do WordPress.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Agradecemos aos esses colaboradores do WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Este lançamento foi liderado por <a href=\"https://profiles.wordpress.org/whyisjake/\">Jake Spurlock</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">O WordPress 7.1.3 não teria sido possível sem as contribuições das seguintes pessoas. Suas contribuições para fornecer soluções de manutenção e segurança em uma versão estável é uma prova do poder e da capacidade da comunidade WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://w.org/@jorbin\">Aaron Jorbin</a>, <a href=\"https://w.org/@adamsilverstein\">Adam Silverstein</a>, <a href=\"https://w.org/@adrianmoldovanwp\">Adi Moldovan</a>, <a href=\"https://w.org/@adrianduffell\">Adrian Duffell</a>, <a href=\"https://w.org/@xknown\">Alex Concha</a>, <a href=\"https://w.org/@arkaprabhachowdhury\">Arkaprabha Chowdhury</a>, <a href=\"https://w.org/@iamchitti\">Deepak Kumar</a>, <a href=\"https://w.org/@donniam\">donniam</a>, <a href=\"https://w.org/@ehtis\">Ehtisham Siddiqui</a>, <a href=\"https://w.org/@whyisjake\">Jake Spurlock</a>, <a href=\"https://w.org/@audrasjb\">Jb Audras</a>, <a href=\"https://w.org/@jeremyfelt\">Jeremy Felt</a>, <a href=\"https://w.org/@joedolson\">Joe Dolson</a>, <a href=\"https://w.org/@johnbillion\">John Blackbourn</a>, <a href=\"https://w.org/@jonsurrell\">Jon Surrell</a>, <a href=\"https://w.org/@desrosj\">Jonathan Desrosiers</a>, <a href=\"https://w.org/@kgagne\">Ken Gagne</a>, <a href=\"https://w.org/@khokansardar\">Khokan Sardar</a>, <a href=\"https://w.org/@lancewillett\">Lance Willett</a>, <a href=\"https://w.org/@lucatume\">lucatume</a>, <a href=\"https://w.org/@marcs0h\">marcs0h</a>, <a href=\"https://w.org/@peterwilsoncc\">Peter Wilson</a>, <a href=\"https://w.org/@pkevan\">pkevan</a>, <a href=\"https://w.org/@therssoftware\">RS Software</a>, <a href=\"https://w.org/@rfaile313\">Rudy Faile</a>, <a href=\"https://w.org/@sergeybiryukov\">Sergey Biryukov</a>, <a href=\"https://w.org/@siliconforks\">siliconforks</a>, <a href=\"https://w.org/@smerriman\">smerriman</a>, <a href=\"https://w.org/@sabernhardt\">Stephen Bernhardt</a>, <a href=\"https://w.org/@suryakantupadhyay\">Suryakant Upadhyay</a>, <a href=\"https://w.org/@vortfu\">vortfu</a>, <a href=\"https://w.org/@webverts\">webVerts</a>, <a href=\"https://w.org/@westonruter\">Weston Ruter</a> e <a href=\"https://w.org/@yogeshbhutkar\">Yogesh Bhutkar</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Como cortesia, as correções de segurança estão sendo retro compatibilizadas, quando necessário, para todas as versões elegíveis para receber correções de segurança (atualmente a partir da versão de 4.7). Como lembrete, <strong>apenas a versão mais recente do WordPress é ativamente suportada</strong>. Os backports estão em andamento e serão enviados à medida que se tornam prontos.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Como contribuir</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Para se envolver no desenvolvimento do núcleo do WordPress, vá até o Trac, <a href=\"https://core.trac.wordpress.org/report/6\">escolha um ticket</a> e participe da conversa no canal <a href=\"https://wordpress.slack.com/archives/C02RQBWTW\">#core</a>. Precisa de ajuda? Confira o <a href=\"https://make.wordpress.org/core/handbook/\">Manual do contribuidor do núcleo</a>.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"3734\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:4:\"href\";s:35:\"https://br.wordpress.org/news/feed/\";s:3:\"rel\";s:4:\"self\";s:4:\"type\";s:19:\"application/rss+xml\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:44:\"http://purl.org/rss/1.0/modules/syndication/\";a:2:{s:12:\"updatePeriod\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"\n	hourly	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:15:\"updateFrequency\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"\n	1	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:4:\"site\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"13096052\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";a:12:{s:6:\"server\";s:5:\"nginx\";s:4:\"date\";s:29:\"Sun, 22 Nov 2026 15:33:02 GMT\";s:12:\"content-type\";s:34:\"application/rss+xml; charset=UTF-8\";s:4:\"vary\";s:37:\"Accept-Encoding, accept, content-type\";s:6:\"x-olaf\";s:3:\"⛄\";s:13:\"last-modified\";s:29:\"Wed, 18 Nov 2026 17:36:11 GMT\";s:4:\"link\";s:61:\"<https://br.wordpress.org/wp-json/>; rel=\"https://api.w.org/\"\";s:15:\"x-frame-options\";s:10:\"SAMEORIGIN\";s:16:\"content-encoding\";s:4:\"gzip\";s:7:\"alt-svc\";s:5:\"clear\";s:13:\"x-remembering\";s:58:\"Eric Binnion <https://friendsofericbinnion.wordpress.com/>\";s:4:\"x-nc\";s:9:\"HIT dca 2\";}s:5:\"build\";i:1760654736;s:21:\"cache_expiration_time\";i:1795404782;s:23:\"__cache_expiration_time\";i:1795404782;}','off'),(166,'_site_transient_timeout_feed_mod_b85365aa61afaf3d4189819a6f57c4c4','1795404782','off'),(167,'_site_transient_feed_mod_b85365aa61afaf3d4189819a6f57c4c4','1795361582','off'),(168,'_site_transient_timeout_feed_d117b5738fbd35bd8c0391cda1f2b5d9','1795404783','off'),(169,'_site_transient_feed_d117b5738fbd35bd8c0391cda1f2b5d9','a:6:{s:5:\"child\";a:1:{s:0:\"\";a:1:{s:3:\"rss\";a:1:{i:0;a:6:{s:4:\"data\";s:3:\"\n\n\n\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:7:\"version\";s:3:\"2.0\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:1:{s:7:\"channel\";a:1:{i:0;a:6:{s:4:\"data\";s:112:\"\n	\n	\n	\n	\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"WordPress Planet\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"language\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"en\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"WordPress Planet - http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"item\";a:50:{i:0;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:25:\"Matt: The Spacefast Story\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155411\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://ma.tt/2026/11/spacefast/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:14278:\"<figure class=\"wp-block-image alignwide size-large\"><a href=\"https://spacefast.com/\"><img alt=\"Make it with Spacefast\" class=\"wp-image-155413\" height=\"340\" src=\"https://i0.wp.com/ma.tt/files/2026/11/makeitwith-spacefast-1024x576.webp?resize=604%2C340&#038;quality=80&#038;ssl=1\" width=\"604\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Weekend is starting, Anthropic has IPO&#8217;d, and it&#8217;s time to vibe code. Yes, the <a href=\"https://wordpress.org/\">WordPress</a> guy is launching something where you never have to see a wp-admin dashboard (unless you want to). <img alt=\"🙂\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f642.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\">Like all great products, <a href=\"https://spacefast.com/blog/spacefast-and-beyond/\">Spacefast launched with a manifesto from its founder, Batuhan İçöz</a>:</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">People who never thought of themselves as builders are making software. They’re making presentations, games, websites, and little tools for themselves and their work. HTML is quickly becoming the new PowerPoint, agent-made dashboards are replacing a whole category of business intelligence tools, ease of managing everything with code is removing the need for CMS for many sites. We are speeding into a world where describing your favorite to-do app and seeing it come to life is going to be easier and faster than finding the perfect app for you.</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">Please <a href=\"https://spacefast.com/blog/spacefast-and-beyond/\">read the whole thing</a>! I&#8217;ve had so much fun working with Batu this year and seeing this little nugget of an idea get more and more ambitious.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A good way to try out <a href=\"https://spacefast.com/\">Spacefast</a> is to wait until your AI makes an artifact for you, then tell it:</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">Put this on <a href=\"https://spacefast.com\" rel=\"noopener\" target=\"_blank\">Spacefast.com</a> and send me the link.</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">Or if you want to be fancy, point it to <a href=\"https://spacefast.com/setup.md\">https://spacefast.com/setup.md</a>. If you think your AI is cool now, wait until you give it a real database! One we&#8217;ve scaled to billions of rows and trillions of queries over the decades. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Any agent can publish something there for 33.3 hours, a time period we randomly picked with no significance whatsoever. If you want something to stay up longer, you can register with your email, WordPress.com, Google, or X account. I believe the future is much more &#8220;bring your own model&#8221;/BYOM than trying to outpace the progress of the frontier labs.</p>\n\n\n\n<figure class=\"wp-block-image alignwide size-large\"><a href=\"https://spacefast.com/\"><img alt=\"Spacefast features: shareable links, private sharing, version history, on-page comments, a database, file uploads, and stats.\" class=\"wp-image-155426\" height=\"584\" src=\"https://i0.wp.com/ma.tt/files/2026/11/spacefast-features-1024x990.jpeg?resize=604%2C584&#038;quality=89&#038;ssl=1\" width=\"604\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The free tier is absurdly generous for early adopters: 20 Spaces, 20 custom domains, a million dynamic requests and a terabyte of cached traffic a month, commercial use allowed, no credit card, and no surprise bills. At $5/mo you unlock more Spaces, hourly database backups, and your pick of datacenter, and at $15/mo, teams.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Play With It!</h2>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;ve found Spacefast useful for having my Claude and Codex work on the same artifact, for sharing within <a href=\"https://automattic.com/\">Automattic</a> using the teams feature without worrying about leaking proprietary data, for spinning up silly games or apps on a whim, and for giving my friends who (rightly!) enjoy using Replit, Lovable, or Cloudflare another place they can point their agent to that might be less expensive, might give them some more forward compatibility with Open Source and no vendor lock-in, and might unlock superpowers for them in the future.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One of my goals behind the Radical Speed Month experiment, where about a third of the company split into teams of one to three and worked on whatever they felt most called to, was to give people a chance to express their creativity and drive outside of the normal framework of Automattic&#8217;s products and processes. It was the beginning of this new version of Automattic, experimenting our way into the future of work again, and Spacefast came out of it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There&#8217;s a lot more to the story of how you make an environment where something like Spacefast can be created inside of an existing company, how founder energy can really seem dissonant inside a bigger corporation but is actually critical for survival, and how to protect successful experiments from helpful smothering, but I&#8217;ll save that for another day. Right now I want to just give kudos to the launch team of <a href=\"https://piszek.com/\" rel=\"noopener\" target=\"_blank\">Artur Piszek</a>, <a href=\"https://bt.hn\" rel=\"noopener\" target=\"_blank\">Batuhan İçöz</a>, <a href=\"https://gravatar.com/evilluendas\" rel=\"noopener\" target=\"_blank\">Eduardo Villuendas</a>, <a href=\"https://fka.dev\" rel=\"noopener\" target=\"_blank\">Fatih Kadir Akın</a>, <a href=\"https://jameswrutherford.org/\" rel=\"noopener\" target=\"_blank\">James Rutherford</a>, and <a href=\"https://stefano.sala.io/\" rel=\"noopener\" target=\"_blank\">Stefano Sala</a> for embodying the <a href=\"https://automattic.com/creed/\">Automattic Creed</a> and writing a new chapter in the book of WordPress. It&#8217;s a small team, but Spacefast gets superpowers from across Automattic. You can <a href=\"https://discord.gg/spacefast\">geek out with the team on Discord</a> about the super-creative ways they use <a href=\"https://wp.cloud/\">WP Cloud</a> and all the infrastructure we&#8217;ve built.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Choose Freedom</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Just as when humans gain wisdom they grok and choose Open Source whenever they can, as agents gain intelligence, I believe they&#8217;ll find the Freedom and Agency an Open Source foundation can provide, with battle-tested, secure, and scalable primitives, to be irresistible. And I think if you spend your money with companies that support freedom-expanding rather than freedom-restricting licenses, our future will be a lot brighter.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;s so fun to be making software right now! Between the intelligence jumps of the frontier and the optimizations making local and private inference so useful, there&#8217;s a world of possibilities opening up.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Across Automattic we have teams shipping like never before. On something new like Spacefast, <a href=\"https://x.com/SpacefastHQ/status/2119856305019969566\">they&#8217;ll commit to something crazy like 30 days of new features</a>. On the Open Source projects we contribute to, it <a href=\"https://make.wordpress.org/security/2026/10/29/the-core-security-initiative-two-months-in/\">shows up as the Core Security Initiative closing nearly 3,000 reports in a year when WordPress received more of them than in the previous 12 years combined</a>, which is the tip of the iceberg for what&#8217;s been going on across the millions of WordPresses and customers we support. </p>\n\n\n\n<h2 class=\"wp-block-heading\">The Backstory</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You thought this story started in April 2026 with Radical Speed Month, but it actually starts in 2010! <a href=\"https://www.newyorker.com/magazine/2010/04/19/the-memory-kitchen\">Elif Batuman wrote &#8220;The Memory Kitchen&#8221; for <em>The New Yorker</em> about a chef, Musa Dağdeviren, bringing ancient recipes and ingredients back to life</a>, and her words entranced me so much I knew I had to visit <a href=\"https://www.ciya.com.tr/index_en.php\">his restaurant</a> in Istanbul. </p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"Cooks in white hats and striped aprons serve customers from rows of pots at Çiya\'s busy counter in Istanbul.\" class=\"wp-image-155432\" height=\"390\" src=\"https://i0.wp.com/ma.tt/files/2026/11/image.png?resize=604%2C390&#038;quality=80&#038;ssl=1\" width=\"604\" /><figcaption class=\"wp-element-caption\">Musa Dağdeviren (right) in the kitchen at his restaurant Çiya Sofrasi. Photograph by Carolyn Drake</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Through <a href=\"https://ma.tt/contact/\">my contact form</a> I got the best cold pitch I&#8217;ve ever gotten, from <a href=\"https://private.travel/\">travel wizard Darin Jensen</a>, about how cool Turkey was, so my friend <a href=\"https://tim.blog/\">Tim Ferriss</a> and I decided to have another adventure.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"Tim Ferriss with a buzz cut and a video-game T-shirt in a crowded Istanbul market street.\" class=\"wp-image-34791\" height=\"402\" src=\"https://i0.wp.com/ma.tt/files/2010/05/MCM_7088-1024x681.jpg?resize=604%2C402&#038;quality=89&#038;ssl=1\" width=\"604\" /><figcaption class=\"wp-element-caption\">One of the last times we both got haircuts together</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">We both spoke at WordCamp Turkey in Istanbul, and during my Q&amp;A I got a question from a kid whose name you&#8217;ll recognize:</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\"><strong>Batuhan İçöz:</strong> Seven years ago, you created WordPress as blogging software. Today, a lot of users use WordPress as content management software. How do you define WordPress? Is it blogging software or content management software?</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Ma.tt Mullenweg:</strong> I guess a deeper question would be, how do I define content management software? Historically, CMSs have meant software that’s really hard to use, sucks, and has the whole kitchen sink thrown in. It’s got 50 screens, makes 80 database tables, and does really, really complex things. The idea is that it does everything, so people will choose it. In reality, it ends up doing nothing well, a jack of all trades, master of none.<br /><br />How I think of WordPress is shifting that a little bit. I sometimes refer to WordPress as a content management kernel, much in the same way an operating system has a kernel. WordPress is in the very middle. We want to be small, light, fast, easy to use, and, most importantly, modular.<br /><br />So the idea is that there are 10,000 plugins available to do the kitchen sink. Whatever weird thing you want to do on your site, you can pick the plugin that enables you to do that. The beauty of that is that we don’t have to build all those features in. WordPress doesn’t need to get super bloated to have as many users as we do. We can keep the core really small and have plugins that serve the needs of different communities. There’s a plugin to turn it into a store for e-commerce. There’s a plugin to do collaborative editing of a book. It’ll do pretty much anything you can imagine, and most things you wouldn’t imagine.<br /><br />That is the vision of WordPress, and also why it’s been successful.</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">What a prescient question! We are still talking about canonical plugins today. Batuhan had come to WordCamp because he followed a lot of the people there on <a href=\"https://en.wikipedia.org/wiki/FriendFeed\">Bret Taylor&#8217;s FriendFeed</a>, basically an early fediverse-like aggregator.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Tim and I ended up hanging out with a few WordCampers after the conference, and adorably <a href=\"https://ma.tt/2010/05/wordcamp-istanbul/\">there&#8217;s a picture of Batu and me in my 2010 photoblog</a>.</p>\n\n\n\n<figure class=\"wp-block-image alignwide size-large\"><img alt=\"Matt Mullenweg and Batuhan İçöz in a park in Istanbul.\" class=\"wp-image-34931\" height=\"402\" src=\"https://i0.wp.com/ma.tt/files/2010/05/MCM_7399-1024x681.jpg?resize=604%2C402&#038;quality=89&#038;ssl=1\" width=\"604\" /><figcaption class=\"wp-element-caption\">Me in Thomas Pink, Batu in an awesome Def Jam t-shirt</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">A few weeks later he turned 15. A few months after that, he bought the <a href=\"https://wordpress.com/blog/2006/08/04/custom-css/\">$15/yr Custom CSS upgrade on WordPress.com</a> and <a href=\"https://www.quora.com/What-does-code-is-poetry-mean/answer/Batuhan-Icoz\">posted about Code is Poetry on Quora</a>. Thirteen years later, he&#8217;d join Automattic when <a href=\"https://ma.tt/2023/10/texts-joins-automattic/\">we acquired Kishan Bagaria&#8217;s company, Texts.com</a>. Three years after that, he&#8217;d turn a month-long hackathon project into a movement to reinvent the core principles and freedoms of WordPress for a new generation with <a href=\"https://spacefast.com/\">Spacefast</a>. Wow</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Other Automatticians:</strong> <a href=\"https://obifelten.com/meet-spacefast-everything-your-ai-needs-to-bring-your-ideas-to-life/?utm_source=chatgpt.com\">Obi Felten on putting Spacefast to work</a>, <a href=\"https://robs.club/2026/11/10/spacefast-made-me-a-developer/\">Rob Pugh on becoming a better developer</a>, <a href=\"https://jordangillman.blog/how-spacefast-helps-me-ship-my-every-whim/?utm_source=chatgpt.com\">Jordan Gillman on shipping his every whim</a>, <a href=\"https://jen.mcfadden.blog/2026/11/10/i-built-our-family-a-task-manager-using-spacefast/\">Jen McFadden on building her family a task manager</a>, and <a href=\"https://www.pootlepress.com/2026/11/were-replaying-the-browser-wars-of-20-years-ago-and-software-companies-are-caught-in-the-crosshairs/?utm_source=chatgpt.com\">Jamie Marsland on avoiding the next generation of lock-in</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 21 Nov 2026 05:10:30 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"Akismet: Introducing the official Akismet JavaScript SDK\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://akismet.com/?p=285514\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:73:\"https://akismet.com/blog/introducing-the-official-akismet-javascript-sdk/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:4727:\"<div class=\"wp-block-jetpack-markdown\"><p>Spam doesn’t care what your site runs on. A contact form on a Next.js app or a comment box on a Cloudflare Worker gets the same junk a WordPress blog does. After the <a href=\"https://akismet.com/blog/introducing-the-official-akismet-php-sdk/\">PHP SDK</a> in June, we’re excited to release the official JavaScript SDK for Akismet.</p>\n<h2 id=\"who-is-this-for\">Who is this for?</h2>\n<p><code>@automattic/akismet</code> is a TypeScript client for the Akismet API. It’s for developers adding spam protection to comments, contact forms, or signups in a JavaScript backend.</p>\n<ul>\n<li>It covers the whole <a href=\"https://github.com/Automattic/akismet-api\">Akismet API</a>.</li>\n<li>It runs on Node.js 22 and later, and on Bun, Deno, and Cloudflare Workers.</li>\n<li>It comes with typechecked examples for Express, Fastify, Hono, Next.js, and plain <code>node:http</code>.</li>\n</ul>\n<h2 id=\"a-two-minute-quick-start\">A two-minute quick start</h2>\n<pre><code class=\"language-bash\">npm install @automattic/akismet\n</code></pre>\n<p>Then check each submission in the route that receives it. In a Next.js app, that’s <code>app/api/comments/route.ts</code>:</p>\n<pre><code class=\"language-ts\">import {\n  Akismet, AkismetError, ContentType, SpamVerdict,\n} from \'@automattic/akismet\';\n\nconst akismet = new Akismet({\n  apiKey: process.env.AKISMET_API_KEY!,\n  site: \'https://your-site.com\',\n  isTest: process.env.AKISMET_TEST_MODE === \'1\', // Disable learning\n});\n\nexport async function POST(request: Request) {\n  const { comment, name, email } = await request.json();\n  try {\n    const result = await akismet\n      .forRequest(request, { trustedProxyHops: 1 })\n      .check({\n        body: comment,\n        authorName: name,\n        authorEmail: email,\n        type: ContentType.Comment,\n      });\n    console.log(result.verdict);\n    if (result.verdict === SpamVerdict.Discard) {\n      // Akismet is sure it\'s spam. Drop it.\n    } else if (result.isSpam) {\n      // Hold it for moderation.\n    } else {\n      // Publish it.\n    }\n  } catch (error) {\n    if (!(error instanceof AkismetError)) throw error;\n    // Safe to log: the SDK redacts the API key.\n    console.error(error);\n    // Akismet failed or rejected the input. Hold it for review.\n  }\n  return new Response(null, { status: 202 });\n}\n</code></pre>\n</div>\n\n\n\n<div class=\"wp-block-jetpack-markdown\"><p><code>site</code> is the front page of your site. Check out the <a href=\"https://github.com/Automattic/akismet-sdk-js/blob/trunk/README.md\">README</a> for details on how the the <a href=\"https://github.com/Automattic/akismet-sdk-js/blob/trunk/README.md#client-ip\">Client IP</a> is configured.</p>\n</div>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\">\n			<div class=\"jetpack-videopress-player__wrapper\"> <div class=\"jetpack-video-wrapper\"></div></div>\n			\n			\n		</figure>\n		\n\n\n<div class=\"wp-block-jetpack-markdown\"><p>Every framework follows the same flow: check the submission, then act on the verdict. You can check out some <a href=\"https://github.com/Automattic/akismet-sdk-js/tree/trunk/examples\">examples</a> for Express, Fastify, Hono, <code>node:http</code>, and Next.js Server Actions.</p>\n<h2 id=\"whatâ€™s-in-1-0\">What’s in 1.0</h2>\n<ul>\n<li><strong>Spammers can’t fake their IP.</strong> Trust only the headers from proxies you allow.</li>\n<li><strong>Your API key stays out of your logs.</strong> Log every error worry free.</li>\n<li><strong>You can tell Akismet when it gets one wrong.</strong> Keep the content you checked and its verdict, when a moderator finds missed spam or a false positive, report it. Akismet learns from those reports, check out the <a href=\"https://github.com/Automattic/akismet-sdk-js/blob/trunk/README.md#feedback\">README</a> for how.</li>\n</ul>\n<h2 id=\"get-started\">Get started</h2>\n<p>The Akismet SDK is open source under the MIT license.</p>\n<ul>\n<li>Find it on <a href=\"https://www.npmjs.com/package/@automattic/akismet\">npm</a>.</li>\n<li>Read the code and docs on <a href=\"https://github.com/Automattic/akismet-sdk-js\">GitHub</a>.</li>\n<li>Building with an AI coding agent? Tell it to read the <code>SKILL.md</code> that ships with <code>@automattic/akismet</code>.</li>\n</ul>\n<p>You’ll need an Akismet API key. The <a href=\"https://akismet.com/pricing/\">Personal plan</a> is name-your-price for personal sites and blogs, and commercial sites need a paid plan sized to their traffic. Your code stays the same whichever plan you’re on.</p>\n<p>Found a bug, or something that doesn’t fit your stack? <a href=\"https://github.com/Automattic/akismet-sdk-js/issues\">Open an issue</a> on GitHub.</p>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 20 Nov 2026 17:35:43 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Derek Springer\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:72:\"WordPress.org blog: Global Partners Across the Third Quarter of the 2026\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=22065\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:70:\"https://wordpress.org/news/2026/11/global-partners-third-quarter-2026/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:9056:\"<div class=\"wp-block-jetpack-tiled-gallery aligncenter is-style-rectangular\"><div class=\"\"><div class=\"tiled-gallery__gallery\"><div class=\"tiled-gallery__row\"><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/G35LxFbWcAAWjyl-scaled-1-1024x771.jpeg?ssl=1\" /></figure></div><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Mannheim-1024x1024.jpg?ssl=1\" /></figure></div></div></div></div></div>\n\n\n\n<p class=\"wp-block-paragraph\">From July through September 2026, the WordPress Community organized 39 events with the financial support of the project&#8217;s five <a href=\"https://events.wordpress.org/sponsor/\">Global Partners</a>: Jetpack, WordPress.com, WooCommerce, Bluehost, and Hostinger. From a small gathering of 56 in Mannheim to a Contributor Day in the Philippines that drew 322 people, and the first-ever WordCamp in Eket, Nigeria, these events brought newcomers, contributors, and builders together around the world. The 39 events were too many to cover in one post, so this recap highlights a few of the moments that stood out.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Events around the world</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The quarter opened in July with <a href=\"https://mannheim.wordcamp.org/2026/\">WordCamp Mannheim</a>, a small event with real range. The 56 attendees covered topics from AI and WordPress block development to current security know-how, along with presentations on values, training, and the open web.</p>\n\n\n\n<figure class=\"wp-block-image size-full\" style=\"margin-right: 0; margin-left: 0;\"><img alt=\"\" class=\"wp-image-22097\" height=\"1365\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Eket.jpg?resize=2048%2C1365&#038;ssl=1\" width=\"2048\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">In August, the momentum moved to Nigeria, where <a href=\"https://eket.wordcamp.org/2026/\">Eket held its inaugural WordCamp</a> on August 15 under the theme &#8220;From Idea to Income: Building Opportunities with WordPress.&#8221; <a href=\"https://eket.wordcamp.org/2026/speaker/engr-aniebiet-udoh-fnse/\">Engr. Aniebiet Udoh</a> took the stage for the keynote, challenging attendees to embrace the global reach of the web: &#8220;The internet has no small towns.&#8221; He urged creators to follow a five-step path:</p>\n\n\n\n<ol class=\"wp-block-list\">\n<li>Notice a local pain</li>\n\n\n\n<li>Solve for one person</li>\n\n\n\n<li>Validate with real use</li>\n\n\n\n<li>Standardize the repeatable core</li>\n\n\n\n<li>Scale to global markets</li>\n</ol>\n\n\n\n<p class=\"wp-block-paragraph\">Later in August, <a href=\"https://philippines.wordcamp.org/2026/\">WordCamp Philippines</a> drew approximately 434 attendees, contributors and first-time attendees, to Iloilo City on August 28-29.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One of the highlights of Contributor Day was the Open Source Library, an activity inspired by the Human Library concept. Instead of borrowing a book, participants could &#8220;borrow&#8221; a person and spend time having a meaningful conversation about their experiences, careers, communities, and journeys in open source.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress.com ran both a booth and a dedicated Community + Education table. The education table alone generated connections with 14 schools and universities, sparked three new meetup applications, and produced a new Campus Connect application from Colegio San Agustin in Bacolod.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Students and first-timers in Uganda</h2>\n\n\n\n<p class=\"wp-block-paragraph\">In Uganda, WordPress is reaching people who have never worked with it before. The third edition of <a href=\"https://masaka.wordcamp.org/2026/\">WordCamp Masaka</a> welcomed students and first-timers to participate in a hands-on WordPress Practical session. Led by community members, <a href=\"https://profiles.wordpress.org/stephendumba1/\">Stephen Dumba</a> and Cinderella Mbabazi, <a href=\"https://www.linkedin.com/in/namyalo-florence-b87a82303/\">Florence Namyalo</a>, the Founder and CEO of RAPCIO, and the IT team of Equator University of Science and Technology, the group installed WordPress, explored the dashboard, and began building websites.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-22075\" height=\"683\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/image-7489660a.jpeg?resize=1024%2C683&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">In September, nearly half of this year&#8217;s participants at <a href=\"https://jinja.wordcamp.org/2026/\">WordCamp Jinja</a> were students. One of them, fascinated by the WordPress ecosystem and its spirit of generosity and inclusivity, drew all the sponsor logos by hand so he could remember them after the event.</p>\n\n\n\n<div class=\"wp-block-jetpack-tiled-gallery aligncenter is-style-rectangular\"><div class=\"\"><div class=\"tiled-gallery__gallery\"><div class=\"tiled-gallery__row\"><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/image-d5ba5422-954x1024.png?ssl=1\" /></figure></div><div class=\"tiled-gallery__col\"><figure class=\"tiled-gallery__item\"><img alt=\"\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/IMG-20261119-WA0223-771x1024.jpg?ssl=1\" /></figure></div></div></div></div></div>\n\n\n\n<h2 class=\"wp-block-heading\">From classrooms to community</h2>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-22070\" height=\"447\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/image-9d01fc70.png?resize=1024%2C447&#038;ssl=1\" width=\"1024\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">In September, <a href=\"https://costarica.wordcamp.org/2026/\">WordCamp Costa Rica</a> brought together 327 people. A noteworthy highlight was the pre-event <a href=\"https://developer.wordpress.com/studio/\">WordPress Studio</a> workshop, where 25 participants each built and launched a live site on WordPress.com in a single morning.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The event also demonstrated the growing pipeline from education to community. At least 100 attendees came to WordCamp Costa Rica after first experiencing WordPress through WordPress Campus Connect events at Beenova and UCR Esparza earlier in the year.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The thread running through many of these stories is education and the increasing attendance by students who have been exposed  to WordPress through the WordPress Campus Connect event series. These events serve as a pathway for the next generation of WordPress contributors, builders, and professionals, and each stop this quarter added to that pipeline.</p>\n\n\n\n<h2 class=\"wp-block-heading\">What&#8217;s next</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The current cycle of the Global Partnership Program continues through March of 2027, with WordCamps scheduled in Guatemala, Belo Horizonte, Bandung, and beyond. WordPress Campus Connect events are expanding across Latin America, Southeast Asia, and Africa. Thank you to Jetpack, WordPress.com, WooCommerce, Bluehost, and Hostinger for making this quarter possible, and to every organizer, volunteer, speaker, and attendee who brought these events to life.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images is-style-rectangular is-layout-grid wp-container-core-gallery-is-layout-5a23bf8e wp-block-gallery-is-layout-grid\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://www.bluehost.com/\"><img alt=\"\" class=\"wp-image-22084\" height=\"161\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Bluehost-blue-inline-600px.png?resize=600%2C161&#038;ssl=1\" width=\"600\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://www.hostinger.com/\"><img alt=\"\" class=\"wp-image-22083\" height=\"205\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Hostinger-logo-primary.png?resize=1024%2C205&#038;ssl=1\" width=\"1024\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://jetpack.com/\"><img alt=\"\" class=\"wp-image-22081\" height=\"388\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Copy-of-jetpack-logo-horizontal-color.png?resize=1024%2C388&#038;ssl=1\" width=\"1024\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://wordpress.com/\"><img alt=\"\" class=\"wp-image-22082\" height=\"292\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/Copy-of-wordpressdotcom_lockup-black.png?resize=1024%2C292&#038;ssl=1\" width=\"1024\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://woocommerce.com/\"><img alt=\"\" class=\"wp-image-22067\" height=\"523\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/image-c8bae577.png?resize=1024%2C523&#038;ssl=1\" width=\"1024\" /></a></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">To learn more about WordPress community events near you, visit <a href=\"https://events.wordpress.org/\"><strong>events.wordpress.org</strong></a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 20 Nov 2026 17:17:24 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Harmony Romo\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"WordPress.org blog: WordPress Credits Boost Translation\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=22026\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:64:\"https://wordpress.org/news/2026/11/wp-credits-boost-translation/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:3041:\"<p class=\"wp-block-paragraph\">Contributors to the Costa Rican Spanish locale are making WordPress more accessible to Spanish-speaking communities in Costa Rica. Students from local schools and universities have joined the Polyglots team, helping translate WordPress.org projects and review community contributions.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Students from two universities and a bilingual high school in Costa Rica contributed through the <a href=\"https://wordpress.org/education/credits/\">WordPress Credits program</a>, which lets students earn academic credit for contributing to WordPress as part of their studies. On the Polyglots team, contributors suggest translations for WordPress Core, plugins, themes, and WordPress.org sites. Locale editors review and approve those suggestions.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Between September 2025 and November 2026, translation coverage in es_CR rose from 38% to 100% on WordPress.org, from 39% to 98% in the Plugin Directory, and from 45% to 99% in the Forums. WordPress Core reached 99%, while the queue of strings waiting for review fell from 665 to 105.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One participating school, Liceo Experimental Bilingüe José Figueres Ferrer in Cartago, was the first high school in the Americas to implement WordPress Credits through its Student Community Service program, Trabajo Comunal Estudiantil. Its students focused on Polyglots and helped advance the es_CR translations.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">WP Credits pushed me to contribute to something real, not just a class assignment. Going from not knowing what a ‘string’ was to translating hundreds of them was a great feeling, and it showed me that even a ‘small’ contribution like translation genuinely helps people who use WordPress in Spanish every day.</p>\n<cite>Lester Matarrita Rodríguez, Fidélitas, May 2026</cite></blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">The project also produced a resource for new contributors. The video “<a href=\"https://wordpress.tv/2026/10/23/como-contribuir-en-el-equipo-de-traduccion/\">Cómo contribuir en el equipo de traducción</a>” walks viewers through contributing on the WordPress translation platform, using Costa Rican Spanish as an example.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you read and write a language other than English, you can help make WordPress more useful to people in your language. Start with the <a href=\"https://make.wordpress.org/polyglots/handbook/translating/first-steps/\">first steps in the Polyglots Handbook</a> to learn how to suggest translations and take part in the review process. Then check the <a href=\"https://translate.wordpress.org/stats/\">translation stats page</a> to find projects that need work in your locale. Educators can explore the <a href=\"https://wordpress.org/education/credits/\">WordPress Credits program</a> to learn how students can contribute to WordPress as part of their studies.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 20 Nov 2026 13:48:10 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:12:\"Isotta Peira\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:45:\"Open Channels FM: Meet the Open Notes Podcast\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566631\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:52:\"https://openchannels.fm/meet-the-open-notes-podcast/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:102:\"A brief episode sharing recent podcast network updates, sponsor support, and background on the series.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 20 Nov 2026 11:10:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"Matt: TLD Ideas\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155542\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://ma.tt/2026/11/tld-ideas/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:2450:\"<p class=\"wp-block-paragraph\">.jazz — Obviously reach out to the top musicians and see if they&#8217;d like their first name, and direct a percentage of profits toward music education. Programs like Summer Jazz Workshop were a huge part of me becoming who I am today. Premium registration and renewal pricing like .blog.</p>\n\n\n\n<p class=\"wp-block-paragraph\">.php — Not sure about the commercial appeal of this but can definitely do a <a href=\"https://wordpress.org/five-for-the-future/\">Five for the Future</a>, or maybe Fifty for the Future, towards <a href=\"https://thephp.foundation/\">PHP Foundation</a>. I could see .php being kind of a punk web creator brand. PHP in my head is a very hackable, easy way to build web things, though recent versions have gotten more Java-like. (And will programming languages matter anymore?)</p>\n\n\n\n<p class=\"wp-block-paragraph\">.soul — I think just a standard premium pricing model, but maybe a minimum registration of 5 years or more, perhaps closed to humans, with agent-only registration: a place they can store themselves.</p>\n\n\n\n<p class=\"wp-block-paragraph\">.tumblr — Would be nice to give everyone a domain instead of a subdomain or directory address.</p>\n\n\n\n<p class=\"wp-block-paragraph\">.woo — Could be fun as the web equivalent of getting a booth at the farmers market to sell things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">.wordpress — Could go two directions, either lean into the name being a place for well-curated and secured open source, official and vetted resources, or go like .tumblr and let everyone have one. For the latter, since everyone has copied all our primitives, I think we need to introduce some new ones to make a WordPress different from any other CMS.</p>\n\n\n\n<p class=\"wp-block-paragraph\">.matt — The interest in this surprised me. It turns out there&#8217;s a whole social media subculture of &#8220;name&#8221; handles. Maybe a very high price like $111/yr, paired with some of the matt.* domains I own—perhaps an auction to be the top Matt at matt.dentist or matt.accountant, with the idea that you&#8217;d pass the domain on to another Matt when you retire. There are millions of Matts and Matthews in the world, so the TAM is bigger than you would expect. I&#8217;ve been discussing this with the secret matt-cabal on <a href=\"https://make.wordpress.org/contribute/join/\">the .org Slack</a>. I need to be careful or I&#8217;ll start another matt.company.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 20 Nov 2026 07:59:07 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:61:\"Open Channels FM: What to Expect from the Open Signal Podcast\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566622\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:64:\"https://openchannels.fm/what-to-expect-from-open-signal-podcast/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"A look at open source and web trends from a personal vantage with practical insights\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 19 Nov 2026 10:52:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"Donncha: Photo Competition Manager 0.4.0\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"https://odd.blog/?p=89593248\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:60:\"https://odd.blog/2026/11/18/photo-competition-manager-0-4-0/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:7157:\"<p class=\"wp-block-paragraph\">This WordPress plugin, <a href=\"https://wordpress.org/plugins/photo-competition-manager/\">Photo Competition Manager</a>, is for photography clubs that want to run photography competitions. It allows members to upload photos and then vote on each, displaying them in a slideshow if the images are to be projected. Voting is done through a mobile interface. Results are shown immediately.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This version is a significant upgrade but many of the changes are not visible to the end user. The backend was ripped apart and improved so it runs better. Various bugs were squashed, but two major features were added as well:</p>\n\n\n\n<ol class=\"wp-block-list\">\n<li>External judges can judge the photos rather than asking the members to vote. A panel of judges is created and can be individually added to a competition. They are emailed (or given) a link to judge and use a similar interface to the mobile voting interface used previously.</li>\n\n\n\n<li>I added support for interclub competitions which adds more conditions to the competition. It&#8217;s currently based on the <a href=\"https://sacc.ie/\">SACC</a> interclub competition rules (X+2 substitute images, maximum Y images per photographer) but I expect we&#8217;ll add to that in the future. </li>\n</ol>\n\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full wp-lightbox-container\"><img alt=\"\" class=\"wp-image-89593250\" height=\"1640\" src=\"https://odd.blog/files/2026/11/competitions-1.avif\" width=\"2560\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</div>\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full wp-lightbox-container\"><img alt=\"\" class=\"wp-image-89593252\" height=\"2624\" src=\"https://odd.blog/files/2026/11/judge-ballot-1.avif\" width=\"2064\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</div>\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full wp-lightbox-container\"><img alt=\"\" class=\"wp-image-89593253\" height=\"1243\" src=\"https://odd.blog/files/2026/11/type-edit.avif\" width=\"1436\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</div>\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full wp-lightbox-container\"><img alt=\"\" class=\"wp-image-89593255\" height=\"2334\" src=\"https://odd.blog/files/2026/11/upload-1.avif\" width=\"1836\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</div>\n\n<div class=\"wp-block-image\">\n<figure class=\"aligncenter size-full wp-lightbox-container\"><img alt=\"\" class=\"wp-image-89593257\" height=\"1360\" src=\"https://odd.blog/files/2026/11/voting-controls-1.avif\" width=\"2560\" /><button class=\"lightbox-trigger\" type=\"button\">\n			<svg fill=\"none\" height=\"12\" viewBox=\"0 0 12 12\" width=\"12\" xmlns=\"http://www.w3.org/2000/svg\">\n				<path d=\"M2 0a2 2 0 0 0-2 2v2h1.5V2a.5.5 0 0 1 .5-.5h2V0H2Zm2 10.5H2a.5.5 0 0 1-.5-.5V8H0v2a2 2 0 0 0 2 2h2v-1.5ZM8 12v-1.5h2a.5.5 0 0 0 .5-.5V8H12v2a2 2 0 0 1-2 2H8Zm2-12a2 2 0 0 1 2 2v2h-1.5V2a.5.5 0 0 0-.5-.5H8V0h2Z\" fill=\"#fff\">\n			</svg>\n		</button></figure>\n</div>\n\n\n<p class=\"wp-block-paragraph\">A typical workflow would consist of:</p>\n\n\n\n<ol class=\"wp-block-list\">\n<li>Decide if you&#8217;re going to ask your members to vote or use external judges. If it&#8217;s judges, then set them up with their email addresses on the Judges page.</li>\n\n\n\n<li>Set up the required pages on the Setup Wizard page. Those are voting and results pages.</li>\n\n\n\n<li>Create a competition. I would set the start date to 1 or 2 weeks before the judging night, and set the close date to the day after judging night.</li>\n\n\n\n<li>You will already have added the members of your club through the Members page, so with uploads open, send them the upload link.</li>\n\n\n\n<li>Hopefully uploaded images will start appearing over the next few days.</li>\n\n\n\n<li>On judging night, the Voting Controls page is used to close uploads, display the slideshow (optional if it&#8217;s a print competition) and open voting.</li>\n\n\n\n<li>The Voting Controls page will show a QR code for the voting page if you&#8217;re using the password system. Voting by members this way is an honour system. They enter their name, the password and then rate each photo as it is displayed on the slideshow. There is also a voting link system where a link is sent to each member.</li>\n\n\n\n<li>Voting is closed. If desired, a critique slideshow can be done next, and then we move on to the next category.</li>\n\n\n\n<li>When the competition is done, click on the &#8220;Show Results&#8221; button and then the Results page to display the results to the members.</li>\n\n\n\n<li>On the dashboard Results page, there&#8217;s a button to email the members their individual scores. A CSV of the results is also available on this page.</li>\n</ol>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;ve run several test competitions using the development site I use <a href=\"https://github.com/donnchawp/photo-competition-manager\">here</a>, but I welcome bug reports. The 0.3.0 version was used by Blarney Photography Club for the last year and worked with minimum problems, but I spent a lot of time on this version in the last 2 months so the more eyes on it the better.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you don&#8217;t have a WordPress site, I can recommend WordPress.com. The <a href=\"https://wordpress.com/pricing/\">personal plan</a> there is currently €4/month and lets you run plugins. I work for Automattic, who run WordPress.com, so of course I&#8217;d recommend them. <img alt=\"🙂\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f642.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\n\n#PhotoCompetitionManager #Photography #WordPress #WordPressplugin\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 18 Nov 2026 22:39:58 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:7:\"Donncha\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:43:\"WordPress.org blog: WordPress 7.1.5 Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=22035\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"https://wordpress.org/news/2026/11/wordpress-7-1-5-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:7253:\"<p class=\"wp-block-paragraph\">This security release features fixes for multiple issues.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because this is a security release, it is recommended that you update your sites immediately.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can <a href=\"https://wordpress.org/download/\">download WordPress 7.1.5 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates,” and then click “Update Now.” If you have sites that support automatic background updates, the update process will begin automatically.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1.5 is a short-cycle release. The next major release will be version 7.2, currently planned for December 8, 2026.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For more information, please visit the WordPress 7.1.5 <a href=\"https://wordpress.org/documentation/wordpress-version/version-7-1-5/\">HelpHub site</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Security updates included in this release</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>A malformed regular expression that broadened JSON media type matching, fixed as a hardening measure, reported by <a href=\"https://w.org/@batmoo\">Mo Jangda</a> of the WordPress Security Team.</li>\n\n\n\n<li>A multisite privilege escalation issue letting a site Administrator take over a Super Admin account via Customizer menu previews, reported by Yuval Miller.</li>\n\n\n\n<li>A reflected XSS in the legacy media library popup, reported by <a href=\"https://www.anthropic.com/\">Anthropic</a>.</li>\n\n\n\n<li>An XSS in wp_interactivity_data_wp_context() via the store namespace, reported by <a href=\"https://w.org/@jrf\">Juliette Reinders Folmer</a>.</li>\n\n\n\n<li>SQL injection in WP_Meta_Query via nested relation values, reported by <a href=\"https://w.org/@yougina\">Christiaan Swiers</a>.</li>\n\n\n\n<li>Unauthenticated information disclosure exposing private taxonomy terms via the REST API search endpoint, reported by Anthropic.</li>\n\n\n\n<li>Author+ information disclosure exposing user email addresses via the REST API comments endpoint, reported by Ben Bidner of the WordPress Security Team.</li>\n\n\n\n<li>SQL injection via the front page setting in Customizer changeset previews, reported by Rudy Faile of the WordPress Security Team.</li>\n\n\n\n<li>Contributor+ XSS via scripts in oEmbed provider responses, reported by vvh1te3zz.</li>\n\n\n\n<li>Unauthenticated stored XSS via shortcode attributes in comments, reported by <a href=\"https://w.org/@rafiem\">Rafie Muhammad</a> (Awesome Motive, Inc.).</li>\n\n\n\n<li>Unauthenticated denial of service via batched XML-RPC pingbacks, reported by <a href=\"https://w.org/@giovannicintolo\">Giovanni Cintolo</a>.</li>\n\n\n\n<li>Editor+ information disclosure via post and template author assignment in the REST API, reported by Jarda Snajdr of the WordPress Security Team.</li>\n\n\n\n<li>Administrator stored XSS via Customizer previews, reported by Weston Ruter of the WordPress Security Team.</li>\n\n\n\n<li>Author+ authorization bypass via comment editing in the admin, reported by Jesse McNeil.</li>\n\n\n\n<li>Subscriber+ information disclosure via XML-RPC wp.getComments, reported by <a href=\"https://github.com/dlwodnr59\">Jaewook Lee (grze0)</a>.</li>\n\n\n\n<li>A hardening change that removes the block editor&#8217;s Imgur embed variation, whose server-side provider is already gone, reported by Zhengyu Liu, <a href=\"https://jesse-yang.com/\">Jingcheng Yang</a>, and <a href=\"https://gvzhong.github.io/\">Gavin Zhong</a>.</li>\n\n\n\n<li>Contributor+ stored XSS in the Comment Date block via its date format, reported by Weston Ruter and Jeremy Felt of the WordPress Security Team.</li>\n\n\n\n<li>Unauthenticated privilege escalation via Template Part block attributes that could lead to remote code execution, reported by <a href=\"https://w.org/@logano\">Logan Homolka</a>.</li>\n\n\n\n<li>XSS in the block editor via Openverse image metadata, reported by <a href=\"https://w.org/@kq5y\">Shu Takahashi</a> of Velcore Consulting Inc.</li>\n\n\n\n<li>Contributor+ stored XSS in the block editor via media filenames when converting a media block to a File block, reported by CryptoFox.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you to these WordPress contributors</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This release was led by <a href=\"https://w.org/@jeremyfelt\">Jeremy Felt</a>, <a href=\"https://w.org/@jeryj\">Jerry Jones</a>, and <a href=\"https://w.org/@jsnajdr\">Jarda Snajdr</a>. WordPress 7.1.5 would not have been possible without the contributions of the following people:</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://w.org/@jorbin\">Aaron Jorbin</a>, <a href=\"https://w.org/@adamsilverstein\">Adam Silverstein</a>, <a href=\"https://w.org/@xknown\">Alex Concha</a>, <a href=\"https://w.org/@aduth\">Andrew Duthie</a>, <a href=\"https://w.org/@andrewserong\">Andrew Serong</a>, <a href=\"https://w.org/@vortfu\">Ben Bidner</a>, <a href=\"https://w.org/@yougina\">Christiaan Swiers</a>, <a href=\"https://w.org/@villanovachile\">Daniel Rodriguez</a>, <a href=\"https://w.org/@dmsnell\">Dennis Snell</a>, <a href=\"https://w.org/@ehtis\">Ehtisham Siddiqui</a>, <a href=\"https://w.org/@mamaduka\">George Mamadashvili</a>, <a href=\"https://w.org/@giovannicintolo\">Giovanni Cintolo</a>, <a href=\"https://w.org/@gziolo\">Greg Ziółkowski</a>, <a href=\"https://w.org/@isabel_brison\">Isabel Brison</a>, <a href=\"https://w.org/@jsnajdr\">Jarda Snajdr</a>, <a href=\"https://w.org/@jeremyfelt\">Jeremy Felt</a>, <a href=\"https://w.org/@jeryj\">jeryj</a>, <a href=\"https://w.org/@buffer1024\">Jesse McNeil</a>, <a href=\"https://w.org/@johnbillion\">John Blackbourn</a>, <a href=\"https://w.org/@jonsurrell\">Jon Surrell</a>, <a href=\"https://w.org/@desrosj\">Jonathan Desrosiers</a>, <a href=\"https://w.org/@jrf\">Juliette Reinders Folmer</a>, <a href=\"https://w.org/@kirasong\">Kira Schroder</a>, <a href=\"https://w.org/@lancewillett\">Lance Willett</a>, <a href=\"https://w.org/@logano\">Logan Homolka</a>, <a href=\"https://w.org/@lucatume\">Luca Tumedei</a>, <a href=\"https://w.org/@luisherranz\">luisherranz</a>, <a href=\"https://w.org/@marcs0h\">Marc Montpas</a>, <a href=\"https://w.org/@tyxla\">Marin Atanasov</a>, <a href=\"https://w.org/@batmoo\">Mohammad Jangda</a>, <a href=\"https://w.org/@ntsekouras\">Nik Tsekouras</a>, <a href=\"https://w.org/@peterwilsoncc\">Peter Wilson</a>, <a href=\"https://w.org/@rafiem\">Rafie Muhammad</a>, <a href=\"https://w.org/@ramonopoly\">ramonopoly</a>, <a href=\"https://w.org/@rfaile313\">Rudy Faile</a>, <a href=\"https://w.org/@sergey\">Sergey Biryukov</a>, <a href=\"https://w.org/@kq5y\">Shu Takahashi</a>, <a href=\"https://w.org/@westonruter\">Weston Ruter</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">As a courtesy, the security fixes were backported to all branches eligible to receive security fixes (currently through 4.7). As a reminder, only the most recent version of WordPress is actively supported. The backports are in progress and will ship as they become ready.</p>\n\n\n\n<p class=\"wp-block-paragraph\">In WordPress 7.0, 1024 bit certificates were removed from bundled root certificates. This change has been applied to 6.9.12 and earlier as part of this release.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 RC 2 has also been released, containing all applicable fixes.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 18 Nov 2026 17:08:59 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:11:\"Jeremy Felt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:84:\"Open Channels FM: The Real Challenge of AI in Open Source, Maintaining What We Build\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2565627\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:90:\"https://openchannels.fm/the-real-challenge-of-ai-in-open-source-maintaining-what-we-build/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:271:\"AI significantly accelerates code writing and participation in open source, improving contributor productivity by over 50%. However, this leads to higher burdens on maintainers, who must manage low-quality, AI-generated code, affecting project sustainability and quality.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 18 Nov 2026 16:08:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:10;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:89:\"Open Channels FM: Expand Your Corner of the Open Source Ecosystem with Open Channels News\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566613\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"https://openchannels.fm/what-to-expect-from-open-channels-news-podcast/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:111:\"Capture the latest in open source with concise episodes and occasional commentary to broaden your understanding\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 18 Nov 2026 15:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:11;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:108:\"WPTavern: #242 – Mark Westguard on How WordPress Adapts to Rapid Change: the Dot-Com Bubble to AI Hysteria\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=209930\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:122:\"https://wptavern.com/podcast/242-mark-westguard-on-how-wordpress-adapts-to-rapid-change-the-dot-com-bubble-to-ai-hysteria/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:53031:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox Podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case, how WordPress adapts to rapid change the .com bubble to AI hysteria.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox, and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today we have Mark Westguard. Mark has been building websites for over 30 years, starting out in the early days of the web with his agency, Absolute Internet in the UK, before moving to the US and transitioning into product development. He now runs WS Form, a form plugin for WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">During this episode, we get into the evolution of the internet and WordPress through major technological inflexion points. Most recently, the rise of AI. Mark draws comparisons between the AI era and the frenzy of the .com boom, sharing how rapid influxes of investments and hype, can reshape the entire landscape, often faster than the underlying technology can deliver sustainable results.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The conversation focused not just on the opportunities AI brings to developers and end users, such as dramatically lowering the barrier to entry for building websites or plugins, but also the risks and challenges.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We chat about the overwhelming pace of new product creation, and how the real difficulty today isn&#8217;t necessarily building a plugin, but successfully marketing, supporting and sustaining it in a crowded ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Towards the end, we talk about the potential saturation of plugin marketplaces and what this means for the future of WordPress businesses, especially as AI continues to accelerate product development.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Mark says that he&#8217;s embracing AI in his own workflow, but has some nostalgia for the days when coding was a hands-on craft.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Several other points were raised, including the ongoing demand for trusted, supported, software among non-developers, the looming spectre of AI driven security vulnerabilities, and whether traditional CMS platforms like WordPress might see a renaissance if AI hype collapses.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re curious about how AI is shaping, and challenging, the future of WordPress development and product businesses, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you Mark Westguard.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am joined on the podcast by Mark Westguard. Hello, Mark.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:34] <strong>Mark Westguard:</strong> Hello Nathan, how are you?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:35] <strong>Nathan Wrigley:</strong> Yeah, good. We&#8217;re going to have a little bit of a chat today about the landscape of WordPress in the era of AI. Let&#8217;s explore and see where we go.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So Mark, before we begin, bio time, basically, would you give us your little bio? Tell us what you do in the WordPress space.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:50] <strong>Mark Westguard:</strong> In the WordPress space, currently I&#8217;m running, WS Form, which is an online form plugin for WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I&#8217;ve been in the web game far too long. People can&#8217;t see our grey hairs, but I&#8217;ve been building websites for, oh, I want to say about 30 odd years now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Yeah, I&#8217;ve gone through everything from Netscape Navigator through to where we are now with AI. So, have been building websites for many many companies, for many many years.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I had a agency in the UK called Absolute Internet back in the day, back in 1996. And then moved to the States in 2005 and carried on with that, and then got into product about, I want to say eight years ago now. And have been enjoying it, but still dabbling in the agency side of things as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:34] <strong>Nathan Wrigley:</strong> Okay, so you&#8217;ve had a long and storied history. Has there ever been a moment where it&#8217;s felt like so much was in flux, in your past? Because, I think anybody really listening to this would have some intuition that AI is a moment of great inflexion point. Maybe this is par for the course though, over a 30 year period in the internet. Has there been anything which has disrupted things or changed things as rapidly as this?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:56] <strong>Mark Westguard:</strong> I think, for me it was strange because the internet was there when I started university, but definitely was a big game changer for how we accessed information and searched for information.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The next big thing for me was really the .com bubble, and that going bang quite tremendously, which pulled my first agency into the ground. I mean, we went from 40 odd staff to four people in a day. So that was certainly a big flux in the internet industry that hit me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Once that recovered, it&#8217;s been fairly plain sailing, hasn&#8217;t it? There&#8217;s been a lot of gentle progression in the internet game. We&#8217;ve seen CSS 2, CSS 3. We&#8217;ve seen HTML get a little bit better here and there, standards have improved. But nothing like AI. I mean, I remember the first time I typed a question into a bot and got a response back and I was like, okay, this is going to change things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So yeah, we&#8217;re definitely in a big evolution here and one that I think is way more rapid than internet hitting us as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:58] <strong>Nathan Wrigley:</strong> I think the bit that makes it so profound is the fact that we&#8217;ve given over so much of ourselves to the internet. So during the .com boom, there were, I don&#8217;t know, how many desktop computers in the UK. I imagine there&#8217;s significantly more than there were then than there are now. You know, you had to go and find a computer, sit at a computer, switch the computer on, use things like dial up modems to get access.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:22] <strong>Mark Westguard:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:23] <strong>Nathan Wrigley:</strong> And all of that kind of stuff, many obstacles. And now everything is in your pocket. So we do commerce in our pocket. We communicate from our, the device in our pocket. In other words, everything is wedded to the internet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So the idea of things changing rapidly because we&#8217;ve become so accustomed to the internet being kind of like a utility. The rapid change is more profound, even if the change itself might not be so rapid.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Can I actually go back to the .com boom and bust bit? Because I bet a significant proportion of the people listening to this won&#8217;t even know what that was. Do you want to describe it, and how it crept up on you and overnight just decimated probably billions of dollars from stock markets?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:07:05] <strong>Mark Westguard:</strong> Yeah, it was around about, I want to say 2000, right when it hit. And when we first started as an agency, I was building websites using university computers. I didn&#8217;t own a computer. This is what you were talking about. Not everybody could have afford that technology back then.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But we were building websites for the most bizarre stuff. We had people coming in saying, I want to sell curry online. And I want to, anything and everything that they could come up with as with an idea, they were getting funding for.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And we were dealing with small one man bands, but we&#8217;re also dealing with big companies that had huge investment, that was pumped into these internet ideas. And it&#8217;s kind of similar to what&#8217;s happening with AI right now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">There&#8217;s an immense amount of money being invested into it. And the internet went from a handful of university websites, to everybody doing all manner of things online. The investment just got over the top. And then at some point somebody went, you know what, these investments have no ROI on them. There&#8217;s huge amounts of money being poured into this. And, basically the stock market crashed as a result of it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And we had companies literally within a week saying, we are no longer going to be continuing our management contracts with you. Or we don&#8217;t want to build this website with you anymore. We were building $2 &#8211; 300,000 websites for the likes of Safeway and Sony and KPMG and all kinds of stuff. And it just stopped overnight. And it caused a lot of agencies to fall over, just completely fail, within a matter of months.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:08:37] <strong>Nathan Wrigley:</strong> I remember seeing an ad, I was on Kensington High Street in London. I used to work on Kensington High Street, and I remember seeing an ad on a bus stop. So it was a prime bit of real estate in the UK, probably one of the more expensive places that you could put an ad. And it was for an internet product. And the product was that they would come to your workplace, take your shirt, iron it, and bring it back to you. And I remember looking at ad and thinking, is that really what they&#8217;re selling? Genuinely? Like, is there a market for that? And obviously, within a month the .com bubble had burst.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But it was on that level, wasn&#8217;t it? It was the most peculiar ideas that people could come up with. And maybe some of them would&#8217;ve swum now. But back then, everything was sort of sinking. But also nobody had a mechanism to pay for it. We didn&#8217;t have the sort of access to credit and credit cards and Stripe and all of those payment gateways and all of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It was just, we were falling over ourselves to put ideas out there. Nobody seemed to have the capacity to say, no, look objectively, that&#8217;s a silly idea. That there&#8217;s no business there. It was more, let&#8217;s try it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then eventually a bit like happened with the Dutch and the tulips way back. Somebody woke up and said, hang on, there&#8217;s no money being generated by these things. Then presumably the bankers all took one look at each other and went, oh, what have we done.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:04] <strong>Mark Westguard:</strong> Yeah. And there were a lot of big, big ideas out there that caused a lot of that. I had one guy that came in and I won&#8217;t mention the project name, to save the guy&#8217;s grace. But he had come up with an idea to do an online training platform for children. And this guy we found out afterwards had maxed out his credit cards, had remortgaged his house, had got divorced from his wife, and a tiny part of the reason for the collapse around 2000. But it was that kind of thing that was happening all over the place.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:35] <strong>Nathan Wrigley:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:36] <strong>Mark Westguard:</strong> We are seeing a similar thing happening now with AI. There&#8217;s a huge amount of investment going into it. Now I&#8217;m in no way an expert in the financial world and of investment in AI platforms and stuff, but hopefully we don&#8217;t see as big a bang as we did back then.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:10:50] <strong>Nathan Wrigley:</strong> It felt, at the time, it felt really normal until it suddenly didn&#8217;t. Until I saw that ad for that shirt ironing business, I genuinely I just thought, oh, that&#8217;s a good idea. Oh, that&#8217;s interesting. Look what they&#8217;re doing. Look what you can do now. Ads over and over again.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But then as soon as it starts to unravel, you begin to get the intuition. Wow, that really was hysteria. We were all caught up in this hysteria. Whether or not you are a financial expert, it must be obvious to everybody that we are caught up in some kind of AI hysteria at the moment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, it may be that 80% of all of the business ideas based around AI will succeed. Maybe it&#8217;ll be that 80% of them will fail. But have you got any intuitions that point to it being over egged, hysteria? Are there any things that you&#8217;ve seen out in the real world where you&#8217;ve thought, boy, that really does feel like a moment where we ought to be thinking about whether we&#8217;re caught up in mass hysteria here?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:48] <strong>Mark Westguard:</strong> I think AI for me is like the next logical progression. We&#8217;re talking about coding here, right? AI is used for lots of different things, but in terms of coding, it&#8217;s like the next logical transition in terms of making coding accessible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So if I think back to when I was in college and I was writing machine code for chips, literally like bite by bite, that was quite complicated. And then came along programming languages where we could not have to worry about the machine coding. And then we&#8217;ve got things like, for example Basic on a computer, which meant you didn&#8217;t have to worry about some of the more underlying code underneath that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then came the internet with HTML. And then we had page builders. Now I&#8217;ve got AI where we don&#8217;t even have to think about writing a line of code. You can literally just ask it what you want, and hopefully you&#8217;ll get out of it what you want. At every stage it has made working with a computer, and making a computer do something more accessible to more people.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So now my father can just go online and say, hey, build me this website. I want a green background. I want this font, I want it to say this. Write me a paragraph about such and such, and they can pretty much whip something up in an afternoon. A year ago, two years ago, that was him having to learn how to code to do that, or would have to use a drag and drop page editor to do that. So it really has opened up the ability to develop software and websites to a lot more people.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The thing that I&#8217;m seeing is there&#8217;s an awful lot of ideas being developed. People are coming up with ideas. Some people not actually thinking about, is this a project that&#8217;s got legs? Do people need this? There&#8217;s a lot of repetition going on. There&#8217;s a lot of things being built where really, even if you build a website solution or a piece of software, you&#8217;ve still got to market that. You&#8217;ve still got to support it. You&#8217;ve still got to get it out to the masses.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And AI&#8217;s not quite there with that yet. I can&#8217;t just say, right I&#8217;ve built this product, go and market it for me. It&#8217;s still going to need some feet on the ground to actually go out there and sell a product.</p>\n\n\n\n<p class=\"wp-block-paragraph\">When I got into software and I developed WS Form, building the actual plugin was a lot easier than actually getting out there and getting people interested in it, and telling people about why it&#8217;s a good product. That&#8217;s what took the time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:13:57] <strong>Nathan Wrigley:</strong> That&#8217;s a curious insight. So we are in a moment now where almost anybody who&#8217;s got the capacity to type on a computer can build anything. And I&#8217;m seeing that over the internet at the moment. You said multiple things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So there&#8217;s this person that I follow online, I won&#8217;t mention their name. They&#8217;re not in the WordPress space at all. And if you follow their trajectory, about a year ago, they clearly got the intuition that they could build an app. And so they did for the Mac, and it was really great. It was really good little app and it served its purpose. It was quite a small thing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, a year later, I would think it&#8217;s probably fair to say they&#8217;ve probably got about 15 apps. And there was some moment, and I don&#8217;t know when it was, probably about the 10th one in, I suddenly thought, how does this person maintain this? Is this just a case of just, okay, let&#8217;s build another and another and just keep going through that process. Selling, selling more, selling, more selling. But at what point do the people buying that app get the support that they need and the bug fixes that they need? And that I think is maybe a moment that we haven&#8217;t yet faced.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:02] <strong>Mark Westguard:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:02] <strong>Nathan Wrigley:</strong> The marketing bit. You&#8217;ve built a plugin with AI for WordPress, but you don&#8217;t have the capacity to market it. So you build another one, and you build another one, and you build another one. But the few people that bought it, they&#8217;re going to expect updates and what have you. What I&#8217;m basically trying to do is agree with what you said. The wider bit is the harder bit. The selling it, not just building it, and then making sure that those people come back for more later.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:25] <strong>Mark Westguard:</strong> Yeah, I think that&#8217;s one part that a lot of people are missing. I&#8217;m seeing a lot of people saying, hey, I built this and I&#8217;m making X million per month. I don&#8217;t believe a lot of those posts that you see, with these get rich. If that was the case, everyone would be doing it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But, I love AI. It&#8217;s made my ability to bug test and launch new features so much quicker, and so much more efficient. I just worry that there are so many people jumping into wanting to build businesses with it without thinking about all the other stuff that you&#8217;ve got to do to make that business a success.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And that&#8217;s kind of what I saw back in the two thousands. I saw a lot of people just coming up with ideas, running with it. They were starters but they weren&#8217;t finishers. And the actual marketing of that idea, and getting it supported and everything else was the they fell on.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Yeah, it&#8217;s, an interesting time and it&#8217;s really hard to keep up with it all because it&#8217;s moving so quickly. That&#8217;s the bit that for me is a challenge, is just keeping up with the best thing to do. And there are so many people online, on social media that are trying to tell you the best way of doing it. Everyone&#8217;s got their own, way of doing it. I&#8217;ve had to switch a lot of it off. It&#8217;s overwhelming.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:29] <strong>Nathan Wrigley:</strong> Okay, so that&#8217;s a curious insight. And it was where I was going to go next. I genuinely don&#8217;t know what our capacity is to consume this. I don&#8217;t know where all the people are going to come from to buy all these things. In order for us to to buy all these things, we must all be earning to pay for all these things. And in order to earn, we all need to be selling our own things or doing some kind of lucrative work somewhere. You know to shell out for these things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That&#8217;s the bit that I&#8217;m concerned about. I don&#8217;t see where all of these products are going to get revenue from. In the WordPress space, let&#8217;s cast our minds back three years. Competition was tough already. You know, you&#8217;re in a fairly competitive landscape, WordPress forms, there&#8217;s several solutions for that. So that&#8217;s already competitive.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now if you flood the zone with 10 more, 15 more, a hundred more, that means it&#8217;s much more difficult for everybody to achieve the sort of the weight that they need to have to make that profitable.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;s very hard to encapsulate what I&#8217;m trying to say, but it basically boils down to what is our capacity to attend to all of this stuff. And I was thinking this morning, coincidentally before you and I joined the call, I was thinking before computers came along, I know life wasn&#8217;t as rich and wasn&#8217;t as varied, but it was a heck of a lot less noisy. And we really do allow a lot of noise to get into our lives. And it feels like AI, WordPress, it&#8217;s very noisy at the moment. And I don&#8217;t think we&#8217;ve yet crossed that Rubicon. The noise, it&#8217;s become obvious to us how disruptive that noise was.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:07] <strong>Mark Westguard:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:08] <strong>Nathan Wrigley:</strong> I think we&#8217;re still, in many cases, plugin vendors and theme vendors and things are still relying on previous year&#8217;s subscription to renew, but it&#8217;s the next year that I worry about and the year after that. And I don&#8217;t know if you&#8217;ve got any wisdom there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:18:23] <strong>Mark Westguard:</strong> It&#8217;s an interesting time. I think there&#8217;s a lot of experimenting going on that is being portrayed as the way to do things. There&#8217;s a lot of people, I guess there&#8217;s a lot of people panicking. There&#8217;s even a lot of people in the WordPress world that have gone from WordPress to now saying, I&#8217;m not doing WordPress anymore, and they&#8217;re now a hundred percent AI. And, are they actually producing things that are making them a living? Other than maybe, some of these online content producers. Are there solid products that are coming out of AI?</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you just look at the plugin repo, the number of plugin submissions has gone through the roof because so many people can now just produce utility plugins so quickly and easily. There are still only a handful of people out there actually producing proper products, that are selling as plugins for WordPress, sizable plugins that are really expensive to build with AI. I&#8217;m fortunate that I didn&#8217;t have a suite of small utility plugins. I had quite a large form engine that I intentionally built to be quite complicated, and that&#8217;s kept me afloat.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:23] <strong>Nathan Wrigley:</strong> Oh, I see. You&#8217;ve got like a walled garden around your product a bit because of its complexity, but also it&#8217;s not a utility in the sense that you toggle something on and then something happens on your website. I don&#8217;t know, SMTP plugin or something like that. It just this one thing and it does it, and that&#8217;s all it does.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Yours is much more broad, deep, there&#8217;s a learning curve, but also it performs an essential function on the website. If that was to go away, your forms disappear from your website, that&#8217;s catastrophic potentially. So you&#8217;ve created a bit of a moat around yourself because of that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:19:57] <strong>Mark Westguard:</strong> Yeah, I don&#8217;t think I created it. I just think that happened. Almost the marketing of the product has changed. I used to be pushing, hey, no code forms just drag and drop. Some people don&#8217;t even use the UI anymore. They literally are just using AI to talk to it, because it has the MCP server on it. So it has become more of an engine than a user interface for building a form.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And, we were going to talk briefly about block themes and stuff, on this call and I had recently transitioned my theme on my website from a classic theme to a block theme. And the amount of work that went into that was a lot more than I thought it was going to be with AI. And that&#8217;s because I think AI still is filling in the holes a lot.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So, the more vague your prompt is, the more AI&#8217;s got to do to fit in the gap. So if I just say to it, build me a website, it&#8217;ll build you a website, but you are going to have, umpteen different things that it has assumed that you want along the way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">When I was building my block theme, using AI, there was a lot of prompting I had to do to get it to look the way I wanted it to look. And it took a lot more, I forget how many prompts it was now. It was several hundred prompts in the end to get it where I wanted it to be.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Glad I did it. And I did it a lot quicker than I would&#8217;ve done had I hand coded it for sure. And it did things that I am not very good at doing, like writing a block from scratch, that&#8217;s still something that I struggle with, and it was really helpful to be able to do that with AI.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You see this in social media, people saying, oh, that guy&#8217;s built a website and it looks like it was built from AI. And that&#8217;s basically AI fitting in the gaps with what it&#8217;s been taught that people want. Certain fonts, certain things like that. So you can definitely use it to, I&#8217;ve completely digressed here but, you can definitely build it to build things quicker, but it still takes time to prompt it properly.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And also with someone with programming knowledge, I&#8217;m still steering it in certain directions to make it work the way I want, and to make it work efficiently. I&#8217;ll still look at code that AI generates and be like, what are you doing?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:21:51] <strong>Nathan Wrigley:</strong> I was just going to interrupt there and say, I guess the curious bit about this is that in in every epoch until now, the frailty of the human being, our capacity to forget things, the fact that we can only allocate a certain amount of our brain to a given task. We require sleep and all of these kind of ordinary things. And we get unwell, we&#8217;re not always as efficient one day as we are the next, because we went out the night before, and those kind of things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I suppose that is also a part of the jigsaw puzzle, which has me concerned, is that the state of AI. Let&#8217;s assume a trajectory which is the same as the last five years. Let&#8217;s assume that in the next five years the trajectory&#8217;s going to be the same. Of course it may not turn out that way, but let&#8217;s assume that it does. The worst is now. The worst that an AI can do is today, and tomorrow it will be better, and the day after that, it will be better. And it will never be worse.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so those little wrinkles that you described, you have to prompt it 200 times to get yourself a website. You&#8217;ve got to assume that the combined kind of Borg-like, that&#8217;s a Star Trek analogy, kind of Borg-like nature of AI, is that in a year&#8217;s time, it&#8217;ll be a hundred prompts. The year after that, or six months after that, it&#8217;ll be down to 50, and then 20, and then 10. And you get what I&#8217;m saying.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You know, it just get&#8217;s exponentially better. It never gets worse. That, I think, is the bit that me the most. Is that because it&#8217;s beguiling and because as technologists we love shiny stuff, that we don&#8217;t see this giant problem building behind our backs. That if we&#8217;re constantly beguiled by the shiny, and we give everything over to the AI, maybe there&#8217;ll come a point where we look and we suddenly realise, oh, it&#8217;s now superior than I am in every single regard in terms of website building. So who&#8217;s going to use my services anymore?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:42] <strong>Mark Westguard:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:43] <strong>Nathan Wrigley:</strong> And I find this a curious thing in the WordPress space, because a lot of people seem to be hyping AI to the exclusion of their future selves.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:54] <strong>Mark Westguard:</strong> Yeah. Yep.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:23:55] <strong>Nathan Wrigley:</strong> But they can&#8217;t, it&#8217;s irresistible. You have to do it, because if you don&#8217;t, your competitor will. And so you know, the arms race argument comes out and on we go. And it&#8217;s a curious thing that we&#8217;re in this moment.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:08] <strong>Mark Westguard:</strong> It&#8217;s a funny time for sure. It&#8217;s the buzzword. It&#8217;s what everybody&#8217;s focusing on right now. I&#8217;m doing it. I am using it as much as I can. It&#8217;ll be silly for me not to do that. I embrace it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You know, I was working with James LePage and his team at Automattic when they were developing all of the different AI building blocks. And he very kindly kept me ahead of what was going on there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I&#8217;m very thankful for that because it&#8217;s one of the things that&#8217;s made my product ahead of some of the competition. And I&#8217;ve got people now recommending WS Form because of the AI capabilities that it has.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But it&#8217;s a completely different way of thinking and working from what I was used to. For me to add a new feature meant adding a new UI interface for it, and writing all of that from scratch. And we were talking before this call that I would probably spend a day or two implementing a new feature and working it out. And I used to love that. That used to be good for my brain.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I was thinking the other day, I am getting to the point where I&#8217;m not thinking anymore. Because I, it just, it&#8217;s doing the thinking part of it for me. But my experience in building just that block theme from my website taught me that, much like going to an agency and telling it what logo you have and what colours you have and how you want things to look and how you want things spaced out. All of that initial discovery period still needs to be done with AI in order to get it to do what you want.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, like you say, it&#8217;s going to be able to do that more and more efficiently. You see that with like Claude design where you can set up a, I forget what they call it now, but you kind of build like a design set.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:39] <strong>Nathan Wrigley:</strong> Yeah, like a brand kit kind of thing?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:25:40] <strong>Mark Westguard:</strong> Yeah. Where you give it your logo and your styling and everything else. And you can give it, even the current web address of your site and it&#8217;ll feed that in. And then it can then use that to build new elements.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So, there&#8217;s still a lot of prompted stuff that goes on. I think there&#8217;s a little bit of a myth that you can literally one prompt AI for a lot of things, and get some output from it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One of the interesting things for me is I went to an AI event once, and I met a guy who was, I think he was ex OpenAI. And he said to me and this may or may not be true, but the fundamental software powering everything in AI, the concept behind it has kind of hit a threshold. And what we are now doing is tweaking that and making that work better. We&#8217;re tuning it, fine tuning it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And that&#8217;s where we see an improvement in AI and obviously in processor speed and everything else that&#8217;s going on. So it&#8217;s interesting that kind of the fundamentals of AI are really at a maximum, in terms of what it can do. But it&#8217;s really human tweaking it and training it that&#8217;s making it work an awful lot better. And I think that&#8217;s where a lot of the improvements are going to come from.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:38] <strong>Nathan Wrigley:</strong> You mentioned a little bit ago that you&#8217;ve really not required to write code anymore in order to improve your plugin. You can get AI in the loop there and tweak it and iterate on it that way. Do you miss that though?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:51] <strong>Mark Westguard:</strong> Yeah, I really do.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:53] <strong>Nathan Wrigley:</strong> Is there a bit of you that you could close the box on AI and just rewind the clock and go back to the way it was? Because presumably it wasn&#8217;t all roses and unicorns over there. It was hard work and probably kept you awake at night and you&#8217;re banging your head against the desks, or how do I do this? Is there some kind of halcyon days thinking there, you know, ah it was better before AI. Would you parcel it up and send AI packing if you could, or are you more happy with it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:27:18] <strong>Mark Westguard:</strong> It&#8217;s a love hate relationship for sure. Love hate relationship. I think, much like a carpenter loves doing woodwork. I used to love coding, call me a nerd. But that was my trade. That&#8217;s what I did. And I used to love working things out. And that working out is what kept my brain ticking over.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now if I have something I need to do, I can get AI to build it. Now, I will absolutely, and that&#8217;s hopefully where the quality of my product comes is, I&#8217;ll go and check what it&#8217;s written. I won&#8217;t just implement it and launch it. I will always check what it&#8217;s done, and nine times outta 10 I&#8217;ll find better ways of doing it. Just because of the way that it&#8217;s implemented it. It may not understand that I&#8217;ve got a method in my code somewhere that already does that. So I don&#8217;t want it to recode it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But the more and more I use it, the more it seems to understand my code base, and the way it works. And it&#8217;s getting better and better. It is like having an assistant in the office that can just deal with the coding for me now. But I do miss it. I really do. Sometimes I&#8217;ll just get my hands dirty and do a bit of coding for the old days, but I sit there thinking I could have just prompted AI and it would&#8217;ve done it in five seconds. So it&#8217;s yeah, it&#8217;s weird.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:22] <strong>Nathan Wrigley:</strong> It&#8217;s almost like a hobby. You take time off and pursue a hobby of coding as opposed to the business of coding, which is kind of curious.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:28:28] <strong>Mark Westguard:</strong> Yeah. And I do miss that. Yeah. And it was a hobby. You would get questioned sometimes, what&#8217;s your hobby? And I&#8217;d think, oh, is it? What do I? Do I write swimming or, or eating at a restaurant? I&#8217;m like, no, I actually, yeah, I used to love coding. My hobby was my job, and I was very lucky in that regard that I was doing what I enjoy doing as a career. So that, yeah, part of that&#8217;s missing now. And I do miss it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But at the same time, I love technology and I love seeing new things come to fruition. And I&#8217;ve loved learning about and taking advantage of AI. And there&#8217;s been things in my product that people probably aren&#8217;t even aware that are little bugs that have just been niggling at me that I&#8217;ve never got round to fixing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:08] <strong>Nathan Wrigley:</strong> And now you can.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:08] <strong>Mark Westguard:</strong> I just spend a day and I&#8217;m just like, you know what? Fix that little pixel that&#8217;s out that&#8217;s been bugging me all these years, and it&#8217;ll work it out for me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:16] <strong>Nathan Wrigley:</strong> I am so torn on this subject because I, like anybody that enjoys technology, I really love when I see a new thing. Whether that&#8217;s a piece of hardware or software or the capacity of somebody to do something new, raising the standard of people to do a thing. So on that side of it, it&#8217;s all, like I said, unicorns and rainbows. It&#8217;s brilliant.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But there is a bit of me, which I think growing in size, which is very concerned. And there are so many underpinnings to that. The people growing up now presumably will not be able to go through the process of learning that you went through. Because what would be the point in spending all those hours learning to do all of the things that you had to do and bang your head against the desk. And so that worries me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It worries me that if we flood the landscape, our capacity to engage with that is going to go away. Like, how many Mac apps can we have and how many WordPress plugins can we have? At what point does that marketplace become so saturated that nobody can make a living from that anymore? I don&#8217;t know if that&#8217;ll turn out to be the case. But there&#8217;s just this niggling thing that there&#8217;s maybe going to be some correction.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I think the bit, which seems to be raising its head at the moment is AI&#8217;s capacity to go out and cause mischief in terms of security vulnerabilities and hacking and things like that. And I do wonder if that will be the thing which enables governments, for example, or regulatory authorities and things like that, to say, wait, the brakes need to go on now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:54] <strong>Mark Westguard:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:30:55] <strong>Nathan Wrigley:</strong> We need to figure out how was this allowed to happen? How is it that our banking systems collapsed? Or how is it that the fridges all got switched up to 50 degrees centigrade?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:04] <strong>Mark Westguard:</strong> Which they did.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:04] <strong>Nathan Wrigley:</strong> Which they did. How did we allow this to happen? But at the moment, we&#8217;re in that kind of free market phase of let it all go wild. But I&#8217;m not sure that&#8217;s going to be possible forever.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:16] <strong>Mark Westguard:</strong> I think it&#8217;s going wild on the software side. It&#8217;s also going wild just on the infrastructure side right now. The amount of money that&#8217;s being pumped into building these server farms and everything else, it&#8217;s just off the charts crazy.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Who knows how much this stuff actually costs to run. I feel like we&#8217;re in an age where we&#8217;re getting quite a good deal on this stuff at the moment. Because we&#8217;re in the initial Google phase where Google didn&#8217;t have Google ads. It was literally just a search engine and losing huge amounts of money.</p>\n\n\n\n<p class=\"wp-block-paragraph\">It was only when they monetized it that they started to make some kind of profit, and even that took them a long long time. And we are there with these AI farms. They&#8217;re huge buildings, massive amounts of investment. And we are paying $20 a month to utilise, effectively, we&#8217;ve each got a super computer from a decade or so ago on our desk now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:02] <strong>Nathan Wrigley:</strong> Yeah you&#8217;ve got God-like capabilities for a few dollars a month.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:05] <strong>Mark Westguard:</strong> I know. Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:32:06] <strong>Nathan Wrigley:</strong> It&#8217;s genuinely insane. Okay. So that&#8217;s an interesting point as well. I wonder, so two things here.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The first one is, I wonder if a potential course correction there. The economic model turns out to be unsustainable. And it either collapses or it slowly sort of changes and the fees go up and the capacity to use it goes down. So there&#8217;s that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But also, I wonder if more local AI systems where you download something onto your computer and utilise it there. As opposed to needing the big thing out in the, server farm, the data centre, nobody wants them near their backyard. It certainly seems like that in the UK and it sounds like North America is the same.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The follow on from that is then I wonder if there will be some kind of resurgence for older technology like WordPress. Okay, that was all a bit of fun. We all had a great time playing with the AI, but now that it&#8217;s gone in the way that we got familiar with, let&#8217;s just revive all the things that we knew used to work. Like our old trusty CMS, WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think that&#8217;s that&#8217;s a possibility, right? The curiosity will dwindle in AI and it will return. Certainly that seems to be the kind of pivot that a lot of people in the WordPress space are hoping for. You know, that AI won&#8217;t be able to update your website in the way that clients wish. Use a trusty CMS. AI is going to collapse. Don&#8217;t worry, you&#8217;ve got the old technology like WordPress, that CMS in your back pocket.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I don&#8217;t know if any of those will turn out to be the truth, but certainly an interesting piece to put on the chessboard.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:33:37] <strong>Mark Westguard:</strong> Yeah. And I talk to a lot of plugin developers. Obviously, I&#8217;ve got a big community of friends that build plugins and we&#8217;re all seeing a decline in new customers. And I think part of that is economy. I think part of that is AI. I think that when I think about it and I look at who I&#8217;m looking at like on social media, a lot of those people are very good developers. They&#8217;re people that are pretty high up on the WordPress ladder, and developed tools and have developed software themselves.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But there&#8217;s still a massive user base in WordPress of people that just want to buy a piece of software that&#8217;s tried and tested and works. And don&#8217;t want to have to work out how to do that with AI. And go through that because, you could, get AI and say, okay, build me a plugin. And then they&#8217;re like, okay well, how do I deploy that? How do I test it? How do I do the security on it? Anyway, there&#8217;s a lot that goes into it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And building stuff from scratch, sometimes, isn&#8217;t the best way of doing things. For a lot of people that are developers and know how it all works, it&#8217;s great. I can build utility plugins day in, day out now. I don&#8217;t even build custom field stuff. I don&#8217;t even use a custom field plugin now because I can do that with AI for my own theme. I don&#8217;t need it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If I build a site for a customer, then a lot of the custom stuff I am just writing myself because it&#8217;s a few lines of code and AI can do that for me. But there&#8217;s still people that aren&#8217;t developers. They&#8217;re not coders and they just want to be able to buy a bit of software for 50 bucks or whatever, install it, and then it does its job.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:00] <strong>Nathan Wrigley:</strong> So that&#8217;s a curious thing. And I would fit into that camp. If you took me into any industry apart from web development, WordPress, and you asked me to be confident with, okay, you&#8217;ve got the AI thing over here, or you&#8217;ve got the $50 thing over there, which somebody else is going to maintain, and you can kind of phone them up if the products itself wouldn&#8217;t work.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Genuinely I&#8217;m going to pay for the $50 thing, or the a hundred dollars thing. I would never rely on AI. And think about WordPress websites. The amount of clients that I had over the years, who wouldn&#8217;t even dare to click the save button, because they were terrified that what they were about to do might in some way just destroy the website, you know, and and they would constantly seek reassurance. Are you sure that I can click save? Yeah. Yeah. click save. It&#8217;s absolutely fine. Those people are not going away anywhere.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Although we may become slightly more forgiving of AI, and slightly more trustworthy of it. I think most people in the world, most people in the world, let&#8217;s say this sentence again, have never touched an AI.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:57] <strong>Mark Westguard:</strong> Yeah.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:35:58] <strong>Nathan Wrigley:</strong> They don&#8217;t even know how to interact with it. They wouldn&#8217;t know what to do with it if you put it in front of them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We&#8217;re that tiny cabal of people who because we&#8217;re on the computers already every day AI and code kind of fit hand in glove, we assume that the rest of the world is happy with this stuff and honestly they&#8217;re probably not.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:36:16] <strong>Mark Westguard:</strong> Yeah, and the WordPress world is not a hundred percent developers using it. It&#8217;s, there&#8217;s a lot of just regular end users that want to build a website, or have in the past maybe installed a classic theme or a block theme, or gone to a developer to build themselves the site. But they&#8217;re still using blocks of software to this day.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I mean, every customer that I&#8217;ve got is built on WordPress. They&#8217;re happy with it, they&#8217;re still using it. I work with some very large companies and they&#8217;re still using WordPress as the foundation. And we take advantage of AI to be able to roll things out quicker, which is great.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But if I wanted to, if there&#8217;s a piece of software that&#8217;s quite complicated and that the website relies on it, I won&#8217;t necessarily build that with AI. I&#8217;ll use an off, piece of off the shelf software that is tried and tested and works, and has the support there for it. I do a lot of stuff with Salesforce, for example, and that could be quite complicated. And, it would take a while to get some of the stuff that we&#8217;ve built still done with AI. And there&#8217;s pieces of software that we are running that we just pay, 50 bucks a month for and it works, it does the job.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:14] <strong>Nathan Wrigley:</strong> I think it&#8217;ll be a really interesting moment in the next couple of years seeing where we get with this. Not only whether AI can financially support itself, but whether or not there are outcomes which AI presents to the world that are not aligned to our best interests. Hacking scandals, those kind of things. Whether or not we turn our backs on it and say, put it back. We did enough with AI, we had an experiment with it, and it went slightly pear shaped.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:37] <strong>Mark Westguard:</strong> It was great for cat videos.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:38] <strong>Nathan Wrigley:</strong> It was brilliant for making videos of yourself, or your politician of choice, doing something that they actually didn&#8217;t do. Those kind of things. It was a lot of fun. I mean it&#8217;s so beguiling, but who knows where we&#8217;ll get to in the year 2027, 2028.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:55] <strong>Mark Westguard:</strong> It&#8217;s an interesting time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:57] <strong>Nathan Wrigley:</strong> Let&#8217;s hope we&#8217;re all here to. Yeah, that&#8217;s right. We hope we&#8217;re all here to experience it. Let&#8217;s knock it on the head there. Mark Westguard. Where can we find you online?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:04] <strong>Mark Westguard:</strong> wsform.com. Just go on there. You can find information about the product. You can find me on, I&#8217;m on Twitter, Facebook all over the place. If you search for Mark Westguard, I&#8217;m going to come up. There aren&#8217;t many Mark Westguards in the world, so.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:17] <strong>Nathan Wrigley:</strong> Perfect. Alright, thank you for chatting to me today. I hope that we both get through to 2027. Take care Mark.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:38:23] <strong>Mark Westguard:</strong> Take care. Bye.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have <a href=\"https://www.linkedin.com/in/westguard/\">Mark Westguard</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Mark has been building websites for over 30 years, starting out in the early days of the web with his agency Absolute Internet in the UK, before moving to the US and transitioning into product development. He now runs WS Form, a form plugin for WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">During this episode we get into the evolution of the internet and WordPress through major technological inflection points, most recently, the rise of AI. Mark draws comparisons between the AI era and the frenzy of the dot-com boom, sharing how rapid influxes of investment and hype can reshape the entire landscape, often faster than the underlying technology can deliver sustainable results.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The conversation focused not just on the opportunities AI brings to developers and end-users, such as dramatically lowering the barrier to entry for building websites or plugins, but also the risks and challenges. We chat about the overwhelming pace of new product creation, and how the real difficulty today isn’t necessarily building a plugin, but successfully marketing, supporting, and sustaining it in a crowded ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Towards the end we talk about the potential saturation of plugin marketplaces and what this means for the future of WordPress businesses, especially as AI continues to accelerate product development. Mark says that he&#8217;s embracing AI in his own workflow, but has some nostalgia for the days when coding was a hands-on craft.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Several other points were raised, including the ongoing demand for trusted, supported software among non-developers, the looming spectre of AI-driven security vulnerabilities, and whether traditional CMS platforms like WordPress might see a renaissance if AI hype collapses.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you’re curious about how AI is shaping, and challenging, the future of WordPress development and product businesses, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wsform.com\">WS Form</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 18 Nov 2026 13:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:12;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Matt: New TLDs\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155526\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"https://ma.tt/2026/11/new-tlds/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1513:\"<p class=\"wp-block-paragraph\">For the first time since 2012, there&#8217;s a new round of TLDs being created by ICANN, and we just had <a href=\"https://www.icann.org/en/announcements/details/icann-confirms-2026-round-applications-input-and-objections-period-begins-updated-17-11-2026-en\">string confirmation day</a>!</p>\n\n\n\n<p class=\"wp-block-paragraph\">I&#8217;m happy to share that Automattic is uncontested for .jazz, .php, .soul, .wordpress, .tumblr, .woo, and I personally got .matt.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We have really enjoyed <a href=\"https://my.blog/\">shepherding .blog</a> which has turned into a nice option with a pretty clean namespace (that&#8217;s why we have premium prices on renewal, not just registration) and it&#8217;s had some high profile adoption, for example <a href=\"https://github.blog/\">github.blog</a>, <a href=\"https://stackoverflow.blog/\">stackoverflow.blog</a>, <a href=\"https://seths.blog/\">seths.blog</a> (Seth Godin), <a href=\"https://tim.blog/\">tim.blog</a> (Tim Ferriss), <a href=\"https://www.noahpinion.blog/\">noahpinion.blog</a> (Noah Smith), <a href=\"https://steve.blog/\">steve.blog</a> (Steve Jurvetson), and <a href=\"https://mgs.blog/\">mgs.blog</a> (M.G. Siegler) and ~ 395,000 more. <img alt=\"🤠\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f920.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://newgtldprogram-aps.icann.org/applications\">You can see all the still contested TLDs here</a>.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 18 Nov 2026 10:53:54 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:13;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:64:\"Open Channels FM: Finding Your Edge as the Web Ecosystem Evolves\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2567467\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:71:\"https://openchannels.fm/finding-your-edge-as-the-web-ecosystem-evolves/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:128:\"Remkus de Vries shares how agencies and professionals can adapt to industry changes and take charge of their business direction.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 18 Nov 2026 10:22:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:14;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:20:\"Matt: Who Wrote What\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155520\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:37:\"https://ma.tt/2026/11/who-wrote-what/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:921:\"<p class=\"wp-block-paragraph\">The debates and fire around authorship are playing out faster in literature and other languages than you may be aware of. The best summation of this so far is <a href=\"https://thepointmag.com/examined-life/the-part-about-the-machines/\">Brunella Tipismana Urbano&#8217;s translated from Spanish essay The Part About the Machines</a>.</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">The role of intellectuals is to shed light on these crossroads, to, as George Scialabba <a href=\"https://www.jstor.org/stable/25007119?seq=1\">once wrote</a>, understand their contemporary moral and political significance for the present with singular originality and force. And yet, confronted with a <em>genuinely new phenomenon</em>, our intellectuals have chosen to close their eyes. They have happily chosen ignorance.</p>\n</blockquote>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 18 Nov 2026 01:20:15 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:15;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"WordPress.org blog: WordPress 7.2 Release Candidate 1\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=22019\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:69:\"https://wordpress.org/news/2026/11/wordpress-7-2-release-candidate-1/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:10148:\"<p class=\"wp-block-paragraph\">The first Release Candidate (“RC1”) for WordPress 7.2 is ready for download and testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This version of the WordPress software is still under development</strong>. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, it’s recommended to evaluate RC1 on a test server and site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 RC1 can be tested using any of the following methods:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\" rel=\"noopener\" target=\"_blank\">WordPress Beta Tester</a> plugin on a WordPress install. (Select the “Bleeding edge” channel and “Beta/RC Only” stream.)</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.2-RC1.zip\">RC1 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\">WP-CLI</a> command: <br /><code>wp core update --version=7.2-RC1</code></td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use the <a href=\"http://playground.wordpress.net/release\" rel=\"noopener\" target=\"_blank\">WordPress Playground instance</a> to test the software directly in your browser.  No setup required – just click and go!</td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.2 is <strong>December 8, 2026</strong>. The full <a href=\"https://make.wordpress.org/core/2026/10/06/wordpress-7-2-release-party-schedule/\" rel=\"noopener\" target=\"_blank\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Thank you to everyone who contributes by testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Please continue checking the <a href=\"https://make.wordpress.org/core/\" rel=\"noopener\" target=\"_blank\">Make WordPress Core blog</a> for <a href=\"https://make.wordpress.org/core/tag/7-2\" rel=\"noopener\" target=\"_blank\">7.2-related posts</a> in the coming weeks for more information.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Core Changes Since Beta 5</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Check out the <a href=\"https://wordpress.org/news/2026/10/wordpress-7-2-beta-1-is-ready-for-download-and-testing/\">Beta 1 announcement</a> for details on WordPress 7.2.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can browse the technical details for all issues addressed since Beta 5 using these links:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://core.trac.wordpress.org/query?changetime=11%2F10%2F2026..11%2F17%2F2026&amp;milestone=7.2&amp;status=closed&amp;group=component&amp;order=id&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority\">Closed 7.2 WordPress Core Trac tickets</a> since November 10, 2026</li>\n\n\n\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.2?since=2026-11-10&amp;until=2026-11-17\">7.2 Gutenberg commits</a> since November 10, 2026</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 Release Candidate 1 brings additional bug fixes, accessibility improvements, and compatibility updates as the release moves closer to its December 8 launch.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Recent refinements include fixes to client-side media uploads, improvements to the new random-content redirect feature, and better keyboard navigation through a skip link in the WordPress admin bar. Additional updates improve plugin dependency messaging, script module translations, and the reliability of the HTML and Interactivity APIs.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Developers will also benefit from continued Abilities API refinements and updates to bundled libraries, including PHPMailer, Requests, getID3, and sodium_compat.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://core.trac.wordpress.org/ticket/66490\">Trac #66490</a>, <a href=\"https://core.trac.wordpress.org/ticket/66681\">Trac #66681</a>, <a href=\"https://core.trac.wordpress.org/ticket/66625\">Trac #66625</a>, <a href=\"https://core.trac.wordpress.org/ticket/66331\">Trac #66331</a>, <a href=\"https://core.trac.wordpress.org/ticket/66591\">Trac #66591</a>, <a href=\"https://core.trac.wordpress.org/ticket/65984\">Trac #65984</a></p>\n\n\n\n<h3 class=\"wp-block-heading\">Additional Block Editor Improvements</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.2 RC1 includes further refinements to the block editor, addressing issues with duplicated block content, keyboard interactions on iOS, and revision previews. Improvements to the Interactivity API prevent outdated navigation responses from replacing newer content, while additional fixes improve plugin installation workflows, featured image compatibility, and link suggestions. The transition to modern SVG icons also continues throughout WordPress administration.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Learn more:</strong> <a href=\"https://github.com/WordPress/gutenberg/pull/86839\">GitHub #86839</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/86703\">GitHub #86703</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/86608\">GitHub #86608</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/78367\">GitHub #78367</a>, <a href=\"https://github.com/WordPress/gutenberg/pull/86854\">GitHub #86854</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Want to know more about this release? Here are some highlights:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>New Ipsum default theme</li>\n\n\n\n<li>Expanded responsive design and Gallery controls</li>\n\n\n\n<li>Improved Global Styles and typography tools</li>\n\n\n\n<li>Enhanced Canvas Notes and collaboration</li>\n\n\n\n<li>New DataForm block settings inspector</li>\n\n\n\n<li>Faster media uploads and image processing</li>\n\n\n\n<li>Modernized WordPress admin with SVG icons</li>\n\n\n\n<li>Faster admin navigation and asset loading</li>\n\n\n\n<li>New “On This Day” widget and random post discovery</li>\n\n\n\n<li>Improved translation update management</li>\n\n\n\n<li>Accessibility, security, and PHP 8.6 compatibility improvements</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">How you can contribute</h3>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress is open source software made possible by a passionate community of people collaborating on and contributing to its development. The resources below outline various ways you can help the world’s most popular open source web platform, regardless of your technical expertise.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Get involved in testing</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Testing for issues is crucial to the development of any software. It’s also a meaningful way for anyone to contribute. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Your help testing the WordPress 7.2 RC1 version is key to ensuring that the final release is the best it can be. While testing the upgrade process is essential, trying out new features is equally important. This <a href=\"https://make.wordpress.org/test/2026/10/20/help-test-wordpress-7-2/\" rel=\"noopener\" target=\"_blank\">detailed guide</a> will walk you through testing features in WordPress 7.2.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Update your theme or plugin</h3>\n\n\n\n<p class=\"wp-block-paragraph\">For plugin and theme authors, your products play an integral role in extending the functionality and value of WordPress for all users.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Thanks for continuing to test your themes and plugins with the WordPress 7.2 beta releases. With RC1, you’ll want to conclude your testing and update the <em>“Tested up to”</em> version in your <a href=\"https://developer.wordpress.org/plugins/wordpress-org/how-your-readme-txt-works/\" rel=\"noopener\" target=\"_blank\">plugin’s readme file</a> to 7.2.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you find compatibility issues, please post detailed information to the <a href=\"https://wordpress.org/support/forum/alphabeta/\" rel=\"noopener\" target=\"_blank\">support forum</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Test on your hosting platforms</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Web hosts provide vital infrastructure for supporting WordPress and its users. Testing on hosting systems helps inform the development process while ensuring that WordPress and hosting platforms are fully compatible, free of errors, optimized for the best possible user experience, and that updates roll out to customer sites without issue.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Want to test WordPress on your hosting system? <a href=\"https://make.wordpress.org/hosting/test-results-getting-started/\" rel=\"noopener\" target=\"_blank\">Get started with configuring distributed hosting tests here</a>. Thank you to all <a href=\"https://make.wordpress.org/hosting/test-results/\" rel=\"noopener\" target=\"_blank\">web hosts who help test WordPress</a>!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Curious about testing releases in general? Follow along with the <a href=\"https://make.wordpress.org/test/\" rel=\"noopener\" target=\"_blank\">testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\" rel=\"noopener\" target=\"_blank\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\" rel=\"noopener\" target=\"_blank\">Making WordPress Slack</a>.</p>\n\n\n\n<h3 class=\"wp-block-heading\">An RC1 haiku</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><em>The final bugs fall</em><br /><em>Release candidate takes flight</em><br /><em>Launch day draws nearer</em></p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to <a class=\"mention\" href=\"https://profiles.wordpress.org/audrasjb/\"><span class=\"mentions-prefix\">@</span>audrasjb</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/r1k0/\"><span class=\"mentions-prefix\">@</span>r1k0</a>, and <a class=\"mention\" href=\"https://profiles.wordpress.org/courane01/\"><span class=\"mentions-prefix\">@</span>courane01</a> for collaboration and review.</em></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 17 Nov 2026 16:04:13 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"David Baumwald\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:16;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:72:\"Open Channels FM: What to Expect from the Open Web Conversations Podcast\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566576\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"https://openchannels.fm/what-to-expect-from-open-web-conversations-podcast/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:73:\"Conversations about the state of the open web and what shapes its future.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 17 Nov 2026 11:39:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:17;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:21:\"Matt: Triple Rainbow!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155493\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:37:\"https://ma.tt/2026/11/triple-rainbow/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1072:\"<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-155502\" height=\"284\" src=\"https://i0.wp.com/ma.tt/files/2026/11/Screenshot-2026-11-16-at-5.49.44-PM.png?resize=604%2C284&#038;quality=80&#038;ssl=1\" width=\"604\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">While driving between meetings at the<a href=\"https://www.semafor.com/hub/semafor-silicon-valley-and-the-world-2026\"> Semafor World Conference</a> and San Francisco, I snapped a quick photo of a double rainbow but it turned into a triple rainbow with the iconic <a href=\"https://www.nytimes.com/2019/03/18/us/flintstone-house.html\">Flintstone House</a>.</p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img alt=\"\" class=\"wp-image-155503\" height=\"299\" src=\"https://i0.wp.com/ma.tt/files/2026/11/image-1.png?resize=604%2C299&#038;quality=80&#038;ssl=1\" width=\"604\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">It&#8217;s been a strange few weeks, but driving through the rain and sun and seeing three rainbows reminded me that the storm and the light usually arrive together. Staying optimistic.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 17 Nov 2026 02:02:50 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:18;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"Open Channels FM: The Personal Transition: From Human Code Reviews to AI Collaboration\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566436\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:92:\"https://openchannels.fm/the-personal-transition-from-human-code-reviews-to-ai-collaboration/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:207:\"Adopting AI in software development requires a shift in approach, emphasizing trust, automated processes, and robust guidelines to foster creativity while reducing micromanagement and enhancing productivity.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 16 Nov 2026 16:22:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:19;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"Open Channels FM: What Is Open Channels FM Podcast Network?\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566565\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:65:\"https://openchannels.fm/what-is-open-channels-fm-podcast-network/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:92:\"Meet our four shows dedicated to signal, news, and insight for open source and the open web.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 16 Nov 2026 11:16:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:20;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"bbPress: bbPress 2.6.22 is out!\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"https://bbpress.org/?p=250525\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:55:\"https://bbpress.org/blog/2026/11/bbpress-2-6-22-is-out/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1888:\"<p class=\"wp-block-paragraph\">bbPress 2.6.22 was released on November 15, 2026. It is a security and maintenance release. Everyone running bbPress should update. <img alt=\"🔒\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f512.png\" style=\"height: 1em;\" /></p>\n\n\n\n<p class=\"wp-block-paragraph\">This release strengthens access checks for forums, topics, replies, attachments, REST media changes, BuddyPress group moderation, and public discovery. Protected bbPress content is kept out of sitemaps, attachment comment feeds, embedded content, and listings without the required access.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Maintenance fixes improve topic and forum trash, restore, spam, unspam, and deletion performance, preserve interrupted restore lists, and report failed database queries in the forum reset tool. Block theme rendering, importers, WordPress navigation, BuddyPress compatibility, daylight-saving time handling, and PHP compatibility also improve.</p>\n\n\n\n<p class=\"wp-block-paragraph\">bbPress 2.6.22 still requires WordPress 6.0 or newer and PHP 7.2 or newer, and is tested through WordPress 7.1. The database version remains 264, so no database upgrade is required. Imported Vanilla users with 32-character hexadecimal plaintext passwords may need a reset. The <a href=\"https://codex.bbpress.org/releases/bbpress-2-6-22/\">2.6.22 upgrade notes</a> cover compatibility details.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The 2.7 development branch remains 2.7.0-alpha-4. Thanks to joaquinferrero, zonduu, and konnektiv for contributions included in this release, and to everyone who helped report, review, and test the changes.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://downloads.wordpress.org/plugin/bbpress.2.6.22.zip\">Download bbPress 2.6.22</a> from WordPress.org, or update from your WordPress dashboard when the update is available.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 16 Nov 2026 05:16:08 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:17:\"John James Jacoby\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:21;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"Matt: Eric’s Memorial\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=155474\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:37:\"https://ma.tt/2026/11/erics-memorial/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:1439:\"<p class=\"wp-block-paragraph\"> Eric&#8217;s memorial is today in Wichita Falls, <a href=\"https://friendsofericbinnion.wordpress.com/celebration-of-life/\">there will be a Zoom for people to attend remotely</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://james.blog/2026/11/10/remembering-eric-binnion/\">James Grierson has a great post remembering Eric</a>. <a href=\"https://ma.tt/2026/10/rip-eric/\">More links and my own writing on Eric is here</a>. I can&#8217;t believe it&#8217;s been a month already&#8230; I find myself returning to <a href=\"https://eric.blog/\">his blog</a> or <a href=\"https://friendsofericbinnion.wordpress.com/\">tribute site</a> frequently when going through something tough at work. </p>\n\n\n\n<p class=\"wp-block-paragraph\">In the service pamphlet Eric&#8217;s wife Sara wrote something beautiful, &#8220;Be the things you loved most about him.&#8221; And this quote from Eric himself:</p>\n\n\n\n<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">“Build a life with enough margin to help others when they need it, and enough humility to accept their help when it’s your turn.”<br />— Eric Binnion, <a href=\"https://eric.blog/2026/07/18/no-one-is-coming/\">July 18, 2026</a></p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">Rest in peace, brother. We miss you dearly. Your life and legacy continues to be an inspiration to me and others.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sat, 14 Nov 2026 18:48:16 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:22;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"Dave Smith: What if WordPress was built for Users not Developers – Create not Learn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://aheadcreative.co.uk/?p=1382\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:107:\"https://aheadcreative.co.uk/articles/what-if-wordpress-was-built-for-users-not-developers-create-not-learn/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:541:\"<p>What if the WordPress site editor was designed around what you want to do, not how WordPress is built? In this video I walk through Create Not Learn, an experimental plugin that explores one possible answer. It uses everyday words, starts from tasks rather than menus, and keeps the complex tools out of the way until you need them. We’re using it to test ideas with real people…</p>\n<p><a href=\"https://aheadcreative.co.uk/articles/what-if-wordpress-was-built-for-users-not-developers-create-not-learn/\" rel=\"nofollow\">Source</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 13 Nov 2026 14:55:52 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Dave Smith\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:23;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"Open Channels FM: AI and the Changing Landscape of Game Preservation\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2564536\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"https://openchannels.fm/ai-and-the-changing-landscape-of-game-preservation/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:384:\"Artificial intelligence is reshaping the way classic video games are preserved and enjoyed. As AI-assisted tools become more accessible, developers can reverse engineer, emulate, and port games to hardware and operating systems they were never originally designed for. This trend is lowering the technical barriers that once kept old games locked away on obsolete platforms. [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 13 Nov 2026 14:06:35 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:24;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"WordPress.org blog: Copy Your WordPress Site with Reprint\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=22001\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"https://wordpress.org/news/2026/11/reprint-your-site/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:4378:\"<p class=\"wp-block-paragraph\">Reprint is a free, open-source, PHP-based tool that copies a WordPress site’s files and database. The plugin is available in the <a href=\"https://wordpress.org/plugins/reprint/\">WordPress.org Plugin Directory</a>, along with the command-line client used to copy the site.</p>\n\n\n<figure class=\"wp-block-post-featured-image\"><img alt=\"\" class=\"attachment-post-thumbnail size-post-thumbnail wp-post-image\" height=\"1440\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/reprint-hero-scaled.png?resize=2560%2C1440&#038;ssl=1\" width=\"2560\" /></figure>\n\n\n<p class=\"wp-block-paragraph\">WordPress has long let you <a href=\"https://wordpress.org/documentation/article/tools-export-screen/\">export your posts and pages</a>. Moving the site itself means bringing along its theme, plugins, uploads, and settings, too. Making that easier has been part of <a href=\"https://make.wordpress.org/core/2024/06/21/data-liberation-and-wordpress-migrations/\">WordPress’s Data Liberation work</a> since 2024.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Example use cases</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You can use Reprint to copy your site to a new host, or to create a local copy meant for testing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">While moving your site to a new host, visitors can keep using the original. Use Reprint to copy the site, and then open the copy to check that your pages load, your images appear, and your forms work before you send visitors there. When you’re ready to switch, pause changes on the original site, make one last copy, and point your domain to the new host. The <a href=\"https://developer.wordpress.org/reprint/guides/move-to-another-host/\">step-by-step guide to moving your site</a> walks you through the move.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can also use Reprint to create a site copy meant for testing, a place to try changes without affecting the site your visitors use. <a href=\"https://developer.wordpress.org/reprint/getting-started/copy-a-site/\">Copy your site to your computer</a> or try the <a href=\"https://playground.wordpress.net/?clone-site=https%3A%2F%2Freprint-demo.wordpress.net\">experimental, browser-based option in WordPress Playground</a>. Use the copy to try a new layout with your existing pages, see how a plugin fits into your site, or check that everything still works after a WordPress update.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How Reprint copies a site</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Reprint sends your files and database directly to the computer or server you choose, one piece at a time, without needing to connect to an external service. The transfer can begin without your old host having to make room for an archive of the whole site.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If the connection drops during the copy, you can resume from the last saved point. If you give Reprint a new site address, it can update links that point to the old one. It builds on the <a href=\"https://make.wordpress.org/core/2025/11/27/wordpress-importer-can-now-migrate-urls-in-your-content/\">WordPress Importer’s approach to rewriting links</a> and applies it to the copied database, including links stored in site settings, blocks, shortcodes, and complex data structures like serialized data or custom fields safely without corrupting tables.</p>\n\n\n\n		<figure class=\"wp-block-jetpack-videopress jetpack-videopress-player\">\n			<div class=\"jetpack-videopress-player__wrapper\"> </div>\n			\n			\n		</figure>\n		\n\n\n<p class=\"wp-block-paragraph\">When copying a site repeatedly, Reprint figures out what changed since the last time and copies only the files it needs.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Try Reprint</h2>\n\n\n\n<p class=\"wp-block-paragraph\">You don’t need to connect your own site to see how Reprint works. Try the <a href=\"https://playground.wordpress.net/?clone-site=https%3A%2F%2Freprint-demo.wordpress.net\">experimental, browser-based option in WordPress Playground</a>. You can copy a sample site right in your browser, with nothing to install.</p>\n\n\n\n<p class=\"wp-block-paragraph\">When you’re ready to work with your own pages and settings, start with a test site you manage. The <a href=\"https://developer.wordpress.org/reprint/getting-started/copy-a-site/\">guide to making your first copy</a> takes you from installing the plugin to opening the copied site on your computer.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 13 Nov 2026 12:00:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"Adam Zieliński\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:25;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"Open Channels FM: After the Announcement, Open Channels News Week in Review\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2566831\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:81:\"https://openchannels.fm/after-the-announcement-open-channels-news-week-in-review/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:192:\"This week’s news looked at AI, open-source licensing, security automation, regulatory software, enterprise spending, SaaS alternatives, maintenance challenges, patents, and credential risks.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 13 Nov 2026 10:13:55 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"Open Channels FM\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:26;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:86:\"WordCamp Central: WordPress Campus Connect 2026 at Compact Polytechnic Institute, Feni\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"https://central.wordcamp.org/?p=16786906\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:97:\"https://central.wordcamp.org/news/2026/11/wordpress-campus-connect-compact-polytechnic-institute/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:16569:\"<div class=\"wp-block-group\"><div class=\"wp-block-group__inner-container is-layout-constrained wp-block-group-is-layout-constrained\">\n<div class=\"wp-block-group is-vertical is-layout-flex wp-container-core-group-is-layout-4fc3f8e1 wp-block-group-is-layout-flex\">\n<h3 class=\"wp-block-heading has-black-color has-text-color has-link-color wp-elements-2\">Campus Connect event</h3>\n\n\n\n<p class=\"wp-block-paragraph\">On November 12, 2026, WordPress Campus Connect took place at Compact Polytechnic Institute, Feni, Bangladesh, bringing together students, WordPress enthusiasts, speakers, and community members for a day of learning, knowledge sharing, and exploring opportunities within the global WordPress ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The event was designed to introduce students to WordPress, modern website development, open-source contributions, plugin development, artificial intelligence, and career opportunities in the WordPress ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Throughout the event, participants had the opportunity to learn from experienced speakers, explore different areas of WordPress, and discover how they can become active members of the global WordPress community.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Event Sessions and Speakers</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The event featured five sessions covering different aspects of WordPress, from modern website development to community contributions and career opportunities.</p>\n\n\n\n<h3 class=\"wp-block-heading\">1. Building Modern Websites with Blocks &amp; Full Site Editing</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Speaker:</strong> <a href=\"https://events.wordpress.org/campusconnect/2026/compact-polytechnic-institute-feni/speaker/muhibul-haque/\">Muhibul Haque</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Time:</strong> 10:15 AM (+06)</p>\n\n\n\n<p class=\"wp-block-paragraph\">This session focused on the modern WordPress editing experience and how the Block Editor (Gutenberg) and Full Site Editing (FSE) are transforming website development.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Participants explored different types of WordPress blocks, learned how to combine blocks and patterns to create engaging page layouts, and discovered how block themes work.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The session also covered customizing essential website elements, including headers, footers, templates, and navigation, directly through the WordPress Site Editor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Key topics included:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Introduction to the WordPress Block Editor (Gutenberg).</li>\n\n\n\n<li>Exploring different block types and their practical uses.</li>\n\n\n\n<li>Creating page layouts using blocks and patterns.</li>\n\n\n\n<li>Understanding Full Site Editing (FSE).</li>\n\n\n\n<li>Working with block themes.</li>\n\n\n\n<li>Customizing headers, footers, templates, and navigation.</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">2. Building the WordPress Ecosystem Through Plugin Development</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Speaker:</strong> <a href=\"https://events.wordpress.org/campusconnect/2026/compact-polytechnic-institute-feni/speaker/foysal-imran/\">Foysal Imran</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Time:</strong> 11:00 AM (+06)</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress is not just a website-building platform; it is a growing open-source ecosystem powered by developers and contributors worldwide.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This session introduced participants to the role of plugin development in extending WordPress functionality and solving real-world problems.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The discussion covered the fundamentals of WordPress plugin development, plugin architecture, and how developers can build custom solutions to meet different website requirements.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Participants also learned about contributing plugins to the official WordPress.org Plugin Directory and how open-source development can help them improve their technical skills, build portfolios, and explore career opportunities.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Key topics included:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Introduction to the WordPress ecosystem.</li>\n\n\n\n<li>Understanding WordPress plugin architecture.</li>\n\n\n\n<li>Fundamentals of plugin development.</li>\n\n\n\n<li>Building solutions through custom plugins.</li>\n\n\n\n<li>Contributing to the WordPress.org Plugin Directory.</li>\n\n\n\n<li>Career opportunities through open-source development.</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">3. Getting Started with WordPress Contributions: Learn, Practice &amp; Contribute</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Speaker:</strong> <a href=\"https://events.wordpress.org/campusconnect/2026/compact-polytechnic-institute-feni/speaker/atikur-rahman/\">Atikur Rahman</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>WordPress.org Profile:</strong> <a href=\"https://profiles.wordpress.org/atik0130961/\">Atikur Rahman (@atik0130961)</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Time:</strong> 11:30 AM (+06)</p>\n\n\n\n<p class=\"wp-block-paragraph\">I had the opportunity to lead this session and introduce students to the WordPress open-source community and the different ways they can contribute to the project.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One of the most important messages I wanted to share was that contributing to WordPress is not limited to developers or people with advanced coding knowledge. Anyone interested in learning, sharing knowledge, and helping others can become part of this global community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We explored the different WordPress contribution teams and discussed how people with different skills and interests can contribute to the project.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I also introduced participants to WordPress.org and demonstrated some practical ways to get started with contributing.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The session covered three practical contribution opportunities:</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Creating a WordPress.org Account</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Participants learned about creating their WordPress.org accounts, setting up their profiles, and becoming part of the WordPress community.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Contributing to the Polyglots Team</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">I introduced the WordPress Polyglots team, which works to make WordPress accessible to people around the world through translation.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We explored how contributors can participate in translating WordPress, plugins, and themes into Bangla and help make WordPress more accessible to Bangla-speaking users.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Contributing to the Photo Directory</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Participants also learned about the WordPress Photo Directory and how they can contribute photographs to this open-source resource.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This demonstrated that contributing to WordPress does not always require programming skills. People with different interests and abilities can make meaningful contributions.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Key topics included:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Introduction to the WordPress open-source community.</li>\n\n\n\n<li>Understanding why WordPress contributions matter.</li>\n\n\n\n<li>Exploring different WordPress contribution teams.</li>\n\n\n\n<li>Ways to contribute beyond coding.</li>\n\n\n\n<li>Getting started with WordPress.org.</li>\n\n\n\n<li>Creating a WordPress.org account and setting up a profile.</li>\n\n\n\n<li>Understanding the Polyglots team and Bangla translation.</li>\n\n\n\n<li>Exploring the WordPress Photo Directory.</li>\n\n\n\n<li>Practical demonstrations of contribution opportunities.</li>\n\n\n\n<li>Building skills through open-source collaboration.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">My goal was to help students understand that they do not need to wait until they become professional developers to start contributing. They can begin their contribution journey while learning.</p>\n\n\n\n<h3 class=\"wp-block-heading\">4. WordPress &amp; AI: Exploring Smarter Tools and Practical Applications</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Speaker:</strong> <a href=\"https://events.wordpress.org/campusconnect/2026/compact-polytechnic-institute-feni/speaker/sayeeduzzaman-noor/\">Sayeeduzzaman Noor</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Time:</strong> 12:00 PM (+06)</p>\n\n\n\n<p class=\"wp-block-paragraph\">Artificial Intelligence is changing how websites are developed, content is created, and digital experiences are managed.</p>\n\n\n\n<p class=\"wp-block-paragraph\">This session explored how AI tools can be integrated into everyday WordPress workflows to improve productivity, save time, and make website development more efficient.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Participants discovered how AI-powered tools and plugins can support website creation, content generation, SEO, coding, debugging, and design-related tasks.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The session also included practical examples of using AI in real-world WordPress projects.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Key topics included:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Introduction to AI in the WordPress ecosystem.</li>\n\n\n\n<li>Exploring AI-powered WordPress tools and plugins.</li>\n\n\n\n<li>Using AI for content creation.</li>\n\n\n\n<li>Generating website copy and digital content.</li>\n\n\n\n<li>AI-assisted website development and debugging.</li>\n\n\n\n<li>Improving productivity through AI tools.</li>\n\n\n\n<li>Understanding the opportunities and limitations of AI.</li>\n</ul>\n\n\n\n<h3 class=\"wp-block-heading\">5. Opportunities for Students in WordPress</h3>\n\n\n\n<p class=\"wp-block-paragraph\">This session focused on the opportunities available to students who want to build a future in the WordPress ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress offers opportunities beyond website development, including freelancing, entrepreneurship, open-source contributions, community participation, and professional collaboration.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Participants explored different career paths and learned why developing practical skills, building a portfolio, and participating in the community can help them grow professionally.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Key topics included:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Introduction to the WordPress ecosystem.</li>\n\n\n\n<li>WordPress career opportunities.</li>\n\n\n\n<li>Freelancing and earning opportunities.</li>\n\n\n\n<li>Open-source contributions.</li>\n\n\n\n<li>Portfolio building and skill development.</li>\n\n\n\n<li>Learning roadmaps and career growth.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">My WordPress Journey: From Student to Mentor to Community Speaker</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Being part of this event as a speaker was a meaningful experience for me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">My journey with WordPress started as a student who wanted to learn how websites are built and understand the opportunities available in the WordPress ecosystem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As I continued learning, I discovered something even more valuable: WordPress is not only about building websites. It is also about learning together, sharing knowledge, helping others, and contributing to an open-source project used by people around the world.</p>\n\n\n\n<p class=\"wp-block-paragraph\">After becoming involved in the community, I started contributing to different areas of WordPress and supporting other learners in their journeys.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I completed the WordPress Credits course, became involved in community activities, and later took the opportunity to support students as a mentor.</p>\n\n\n\n<p class=\"wp-block-paragraph\">My involvement in the community gradually grew from being a learner to becoming a mentor and now having the opportunity to share my experience as a community speaker.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Standing in front of students at Compact Polytechnic Institute and sharing what I have learned throughout this journey was a special milestone for me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I wanted students to understand that they do not need to know everything before getting involved. They can start with small steps, learn from the community, contribute according to their abilities, and gradually grow.</p>\n\n\n\n<h2 class=\"wp-block-heading\">A Learning Experience Beyond the Sessions</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Campus Connect is more than a series of presentations. It is an opportunity to introduce students to the possibilities of open-source collaboration and help them see how they can become part of a global technology community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Through the different sessions, students were introduced to modern WordPress website development, plugin development, open-source contributions, AI-powered workflows, and professional opportunities.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Each session highlighted a different part of the WordPress ecosystem and showed how students can explore their interests, develop practical skills, and build their future.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I strongly believe that introducing students to open-source communities at an early stage can create valuable opportunities for both individual growth and the wider WordPress community.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Thank You</h2>\n\n\n\n<p class=\"wp-block-paragraph\">A special thanks to the organizers, speakers, teachers, and students of Compact Polytechnic Institute for making this Campus Connect event possible.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am grateful for the opportunity to share my journey, discuss WordPress contributions, and encourage students to explore the global WordPress community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I also appreciate the enthusiasm and participation of the students throughout the event.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I hope this event inspires more students to start learning WordPress, explore open-source contributions, and become active members of the community.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Looking forward to more opportunities to learn, contribute, mentor, and grow together.</p>\n</div>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/photo1.jpg\"><img alt=\"\" class=\"wp-image-16786909\" height=\"768\" src=\"https://central.wordcamp.org/files/2026/11/photo1-1024x768.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/IMG_4631-scaled.jpg\"><img alt=\"\" class=\"wp-image-16786913\" height=\"768\" src=\"https://central.wordcamp.org/files/2026/11/IMG_4631-1024x768.jpg\" width=\"1024\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/IMG_4570-scaled.jpg\"><img alt=\"\" class=\"wp-image-16809632\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/IMG_4570-768x1024-1.jpg\" width=\"768\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/IMG_4655-scaled.jpg\"><img alt=\"\" class=\"wp-image-16786912\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/IMG_4655-768x1024.jpg\" width=\"768\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://central.wordcamp.org/files/2026/11/IMG_4454-scaled.jpg\"><img alt=\"\" class=\"wp-image-16809633\" height=\"1024\" src=\"https://central.wordcamp.org/files/2026/11/IMG_4454-768x1024-1.jpg\" width=\"768\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-full\"><a href=\"https://central.wordcamp.org/files/2026/11/3f7c72f6-db23-4792-bbdc-81718cf694f0.jpg\"><img alt=\"\" class=\"wp-image-16809635\" height=\"1280\" src=\"https://central.wordcamp.org/files/2026/11/3f7c72f6-db23-4792-bbdc-81718cf694f0.jpg\" width=\"960\" /></a></figure>\n\n\n\n<figure class=\"wp-block-image size-full\"><a href=\"https://central.wordcamp.org/files/2026/11/1d4ec165-ff3d-4461-921e-ae185a7684fb.jpg\"><img alt=\"\" class=\"wp-image-16809636\" height=\"960\" src=\"https://central.wordcamp.org/files/2026/11/1d4ec165-ff3d-4461-921e-ae185a7684fb.jpg\" width=\"1280\" /></a></figure>\n</figure>\n</div></div>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 13 Nov 2026 09:21:42 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:13:\"ATIKUR RAHMAN\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:27;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:75:\"Open Channels FM: Reclaiming Digital Control: Why User Choice Still Matters\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2565724\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:81:\"https://openchannels.fm/reclaiming-digital-control-why-user-choice-still-matters/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lan