024%2C576&#038;ssl=1\" width=\"1024\" /></figure></li><li class=\"wp-block-jetpack-slideshow_slide swiper-slide\"><figure><img alt=\"\" class=\"wp-block-jetpack-slideshow_image wp-image-21952\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/WCAsia-Sponsorship-Prospectus-27.png?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure></li><li class=\"wp-block-jetpack-slideshow_slide swiper-slide\"><figure><img alt=\"\" class=\"wp-block-jetpack-slideshow_image wp-image-21953\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/WCAsia-Sponsorship-Prospectus-28.png?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure></li><li class=\"wp-block-jetpack-slideshow_slide swiper-slide\"><figure><img alt=\"\" class=\"wp-block-jetpack-slideshow_image wp-image-21954\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/WCAsia-Sponsorship-Prospectus-29.png?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure></li><li class=\"wp-block-jetpack-slideshow_slide swiper-slide\"><figure><img alt=\"\" class=\"wp-block-jetpack-slideshow_image wp-image-21956\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/WCAsia-Sponsorship-Prospectus-30.png?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure></li><li class=\"wp-block-jetpack-slideshow_slide swiper-slide\"><figure><img alt=\"\" class=\"wp-block-jetpack-slideshow_image wp-image-21955\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/WCAsia-Sponsorship-Prospectus-31.png?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure></li><li class=\"wp-block-jetpack-slideshow_slide swiper-slide\"><figure><img alt=\"\" class=\"wp-block-jetpack-slideshow_image wp-image-21957\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/WCAsia-Sponsorship-Prospectus-32.png?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure></li><li class=\"wp-block-jetpack-slideshow_slide swiper-slide\"><figure><img alt=\"\" class=\"wp-block-jetpack-slideshow_image wp-image-21958\" height=\"576\" src=\"https://i0.wp.com/wordpress.org/news/files/2026/11/WCAsia-Sponsorship-Prospectus-33.png?resize=1024%2C576&#038;ssl=1\" width=\"1024\" /></figure></li></ul><a class=\"wp-block-jetpack-slideshow_button-prev swiper-button-prev swiper-button-white\"></a><a class=\"wp-block-jetpack-slideshow_button-next swiper-button-next swiper-button-white\"></a><a class=\"wp-block-jetpack-slideshow_button-pause\"></a><div class=\"wp-block-jetpack-slideshow_pagination swiper-pagination swiper-pagination-white\"></div></div></div>\n</div>\n\n\n\n<p class=\"has-text-align-center has-white-color has-text-color has-link-color wp-elements-4 wp-block-paragraph\">Packages are confirmed on a first-come, first-served basis, so reach out early if your company wants to be involved.</p>\n\n\n\n<div class=\"wp-block-buttons is-content-justification-center is-layout-flex wp-container-core-buttons-is-layout-3e41869c wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link has-vivid-red-background-color has-background has-eb-garamond-font-family has-large-font-size has-custom-font-size wp-element-button\" href=\"https://docs.google.com/forms/d/e/1FAIpQLSczlfKKxbOyCN2NAeVmPHE1haqZZu0-a59nxpjTcjEtAomXng/viewform\" rel=\"noopener\" target=\"_blank\"><strong>Become a Sponsor</strong></a></div>\n</div>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\">WordCamp Asia is organized by and for the community. Volunteers, organizers, speakers, sponsors, and attendees each shape what the event becomes, whether they are contributing for the first time or reconnecting with collaborators they have known for years.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped has-border-color has-darker-grey-background-color has-background wp-block-gallery-2 is-layout-flex wp-container-core-gallery-is-layout-db4b8a9e wp-block-gallery-is-layout-flex\" style=\"border-color: 